-- Derek's week 1 (hero derek, days 1-7): episodes, turns, phrases and his calendar.
-- Derek Alvarez, senior developer and Jun's onboarding buddy: the same week as db/seed/14-week1.sql, seen from his side.
-- Push: node tools/dolt.mjs push db/seed/51-derek.sql

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d1_coffee', 'The usual at Nina''s cart', '니나의 카트에서 늘 마시던 걸로', 'coffee_cart', 'nina', 1, 5, '07:00', '10:30', NULL,
   'You have stopped at Nina''s coffee cart every morning for years. Order the usual, make a little small talk, and turn down a muffin politely.', '몇 년째 아침마다 니나의 커피 카트에 들릅니다. 늘 마시던 걸 주문하고, 가볍게 이야기를 나누고, 머핀은 정중히 사양하세요.',
   -5, 9, 10, 'food,coffee,regular,small-talk', 'derek'),
  ('dk_d1_buddy', 'Maya has a favor to ask', '마야의 부탁', 'office_manager', 'maya', 1, 1, '08:30', '12:00', NULL,
   'A new developer starts today. Maya asks you to be his onboarding buddy. Say yes, ask about him, and be honest about your workload.', '오늘 새 개발자가 입사합니다. 마야가 온보딩 버디를 맡아 달라고 합니다. 수락하고, 그에 대해 묻고, 당신의 업무량을 솔직하게 말하세요.',
   0, 0, 20, 'manager,onboarding,mentoring', 'derek'),
  ('dk_d1_standup', 'Your status update', '스탠드업에서 현황 공유', 'office_meeting', 'priya', 1, 1, '09:30', '12:30', NULL,
   'The Monday standup. Give a crisp update: what you wrapped up, what you are picking up, what you are waiting on. Keep a side topic out of the meeting.', '월요일 스탠드업입니다. 끝낸 일, 새로 맡는 일, 기다리는 일을 간결하게 공유하세요. 곁가지 주제는 회의 밖으로 돌리세요.',
   0, 0, 30, 'meeting,standup,status', 'derek'),
  ('dk_d1_welcome', 'Welcoming the new hire', '신입 맞이하기', 'office_desk', 'jun', 1, 1, '09:30', '17:30', 'dk_d1_buddy',
   'Jun is at the desk next to yours on his first day. Welcome him, walk him through the dev setup, and make it easy for him to ask questions.', '준이 첫 출근 날 당신 옆자리에 있습니다. 반갑게 맞이하고, 개발 환경 설정을 차근차근 알려 주고, 편하게 질문할 수 있게 해 주세요.',
   0, 0, 40, 'coworker,mentoring,onboarding', 'derek');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d2_review', 'Talking through the review', '리뷰 코멘트 함께 보기', 'office_desk', 'jun', 2, 2, '09:00', '17:30', NULL,
   'You left twelve comments on Jun''s first pull request, and he looks worried. Talk him through them: praise first, the one real issue, then the nits.', '준의 첫 풀 리퀘스트에 코멘트를 열두 개 남겼더니 그가 걱정스러워 보입니다. 칭찬부터 하고, 진짜 문제 하나와 사소한 지적들을 차례로 설명해 주세요.',
   0, 0, 10, 'dev,code-review,feedback,mentoring', 'derek'),
  ('dk_d2_estimate', 'That is not a two-day job', '이틀짜리 일이 아니에요', 'office_meeting', 'priya', 2, 2, '10:00', '16:30', NULL,
   'Priya told the client that gift card support would take two days. Push back politely, explain why, and offer a timeboxed spike and a trade-off.', '프리야가 고객에게 기프트 카드 지원이 이틀이면 된다고 말했습니다. 정중히 반대하고, 이유를 설명하고, 시간을 정한 사전 조사와 맞바꿀 것을 제안하세요.',
   0, 0, 20, 'meeting,estimate,negotiation,pushing-back', 'derek'),
  ('dk_d2_diner', 'A regular at the Sunny Side', '서니 사이드의 단골', 'diner_counter', 'rosa', 2, 5, '11:30', '14:30', NULL,
   'Rosa knows your usual, but today you go with the special. Swap the side, skip the pie, and settle the check like a regular.', '로사는 당신이 늘 먹는 메뉴를 알지만 오늘은 스페셜을 고릅니다. 사이드를 바꾸고, 파이는 사양하고, 단골답게 계산하세요.',
   -18, 40, 30, 'food,diner,regular,tipping', 'derek'),
  ('dk_d3_one_on_one', 'Where do you go from here?', '앞으로 어디로 갈까요?', 'office_manager', 'maya', 3, 3, '08:30', '12:00', NULL,
   'Your 1:1 with Maya turns to your career. Say you want the tech lead track, take her feedback well, and ask for a stretch assignment.', '마야와의 1:1에서 당신의 커리어 이야기가 나옵니다. 테크 리드 트랙을 원한다고 말하고, 피드백을 잘 받아들이고, 도전적인 과제를 요청하세요.',
   0, 0, 10, 'manager,career,1:1,feedback', 'derek');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d3_tacos', 'Taco lunch with Jun', '준과 타코 점심', 'office_desk', 'jun', 3, 3, '11:30', '13:30', NULL,
   'Jun is about to work through lunch. Invite him to the taco truck, treat him, and chat about tipping and the weekend.', '준이 점심도 거르고 일하려 합니다. 타코 트럭에 같이 가자고 하고, 한턱내고, 팁과 주말에 대해 이야기하세요.',
   -12, 35, 20, 'small-talk,lunch,invitation,food', 'derek'),
  ('dk_d3_planning', 'Sprint planning: holding the line', '스프린트 플래닝: 범위 지키기', 'office_meeting', 'priya', 3, 3, '13:30', '16:30', NULL,
   'Report on your spike, vouch for Jun, and push back when one more feature is squeezed into a full sprint.', '사전 조사 결과를 보고하고, 준을 믿어 주고, 꽉 찬 스프린트에 기능을 하나 더 끼워 넣으려 할 때 반대 의견을 말하세요.',
   0, 0, 30, 'meeting,planning,agile,scope', 'derek'),
  ('dk_d4_incident', 'Checkout is down', '결제가 멈췄어요', 'office_it', 'sam', 4, 4, '08:30', '15:00', NULL,
   'You are on call and production is throwing errors. Work the incident with Sam, then give Maya a clear status update: impact, cause, next steps.', '당신이 온콜 담당인데 운영 환경에서 오류가 쏟아집니다. 샘과 함께 장애를 처리한 뒤, 마야에게 영향·원인·다음 단계를 분명하게 보고하세요.',
   0, 0, 10, 'incident,on-call,status-update,it', 'derek'),
  ('dk_d5_demo', 'Sharing the credit', '공을 나누기', 'office_meeting', 'priya', 5, 5, '10:15', '14:00', NULL,
   'At the sprint demo, give Jun the credit, handle a question you cannot answer, and speak up in the retro.', '스프린트 데모에서 준에게 공을 돌리고, 답할 수 없는 질문에 대처하고, 회고에서 의견을 말하세요.',
   0, 0, 10, 'meeting,demo,retro,credit', 'derek');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('dk_d5_happy_hour', 'Rounding up the team', '해피아워 멤버 모으기', 'office_lobby', 'tom', 5, 5, '15:00', '18:30', NULL,
   'It is Friday and the sky is clear. Invite Tom to happy hour at the Anchor, tell him what you are celebrating, and explain why Jun is taking a rain check.', '금요일이고 하늘이 맑습니다. 톰을 앵커의 해피아워에 초대하고, 무엇을 축하하는지 말하고, 준이 왜 다음으로 미뤘는지 설명하세요.',
   0, 0, 20, 'small-talk,social,invitation', 'derek'),
  ('dk_w_market', 'Groceries for the barbecue', '바비큐 장보기', 'market_checkout', 'mike', 6, 7, '09:00', '21:00', NULL,
   'You are grilling for friends this weekend. Check out at Fairview Market: catch a deal, ask where the charcoal is, and carry it all to the car.', '이번 주말 친구들에게 바비큐를 대접합니다. 페어뷰 마켓에서 계산하세요. 할인을 챙기고, 숯이 어디 있는지 묻고, 짐을 차까지 옮기세요.',
   0, 0, 10, 'shopping,market,barbecue,weekend', 'derek'),
  ('dk_w_park', 'Carl and the lawn mower', '칼과 잔디 깎는 기계', 'park_bench', 'carl', 6, 7, '08:00', '18:00', NULL,
   'You run into Carl, the retired bus mechanic you know from the bus stop, in Seaside Park. Catch up, ask him for a favor, and invite him to the barbecue.', '시사이드 공원에서 버스 정류장에서 알고 지내는 은퇴한 버스 정비사 칼을 만납니다. 안부를 나누고, 부탁을 하나 하고, 바비큐에 초대하세요.',
   0, 0, 20, 'small-talk,neighbor,weekend,homeowner', 'derek');

-- dk_d1_coffee: The usual at Nina's cart

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_coffee', 1, 'nina',
   'The coffee cart on Lake Avenue. Nina spots you in line and is already reaching for a large cup.', '레이크 애비뉴의 커피 카트입니다. 줄 서 있는 당신을 본 니나가 벌써 큰 컵을 집어 듭니다.',
   'Morning, Derek! The usual?', 'Say yes, the usual, please.', '네, 늘 마시던 걸로 달라고 하세요.',
   '[{"all":["usual"]},{"all":["same as always"]}]',
   'Morning, Nina! Yeah, the usual, please.',
   '["Morning, Nina! Is this the line for the bus?","Morning, Nina! I''d like to return this, please.","Morning, Nina! Can I see the dinner menu?"]',
   '["A regular does not need to name the drink.","Key words: the usual"]', '["단골은 음료 이름을 말할 필요가 없습니다.","핵심 단어: the usual"]',
   'nina', 'One large dark roast with room for cream. Coming right up!', '다크 로스트 라지, 크림 넣을 자리 남겨서. 바로 나와요!'),
  ('dk_d1_coffee', 2, 'nina',
   'Nina fills the cup while she talks.', '니나가 이야기하면서 컵을 채웁니다.',
   'So how''s your morning going? Busy day ahead?', 'Say you can''t complain, but it is going to be a busy one.', '그럭저럭 괜찮지만 바쁜 하루가 될 거라고 하세요.',
   '[{"all":["complain"]},{"any":["busy","hectic","packed","slammed"]}]',
   'Can''t complain. It''s going to be a busy one, though.',
   '["It comes with fries, I think.","It''s on the third floor, by the elevators.","I''ll take the Number 12, thanks."]',
   '["Answer the small talk briefly: fine, but a lot to do.","Key words: can''t complain, busy"]', '["잡담에 짧게 답하세요. 괜찮지만 할 일이 많다고요.","핵심 단어: can''t complain, busy"]',
   'nina', 'Then you''ll need this. I made it extra strong.', '그럼 이게 필요하겠네요. 특별히 진하게 내렸어요.'),
  ('dk_d1_coffee', 3, 'nina',
   'A tray of muffins sits next to the register. They smell great.', '계산대 옆에 머핀 한 판이 놓여 있습니다. 냄새가 아주 좋습니다.',
   'Want anything to eat with that? The blueberry muffins just came in.', 'Turn it down politely: say you are good, and that you are trying to cut back on sweets.', '정중히 사양하세요. 괜찮다고 하고, 단것을 줄이는 중이라고 하세요.',
   '[{"all":["i am good"]},{"all":["cut back"]},{"all":["cutting back"]},{"all":["no thanks"]},{"all":["i will pass"]}]',
   'I''m good, thanks. I''m trying to cut back on sweets.',
   '["Yes, I''d like a table for two.","Paper is fine, thanks.","Medium rare, please."]',
   '["In the US, \\"I''m good\\" is a polite way to say no.","Key words: I''m good, cut back on"]', '["미국에서 \\"I''m good\\"은 정중하게 사양하는 말입니다.","핵심 단어: I''m good, cut back on"]',
   'nina', 'Good for you. More for me, then!', '대단하네요. 그럼 제가 더 먹죠!'),
  ('dk_d1_coffee', 4, 'nina',
   'She stamps your punch card. It is full.', '그녀가 쿠폰 카드에 도장을 찍습니다. 칸이 다 찼습니다.',
   'That''s four fifty. And your card is full, so the next one''s on the house.', 'Thank her, tell her to keep the change, and wish her a good day.', '고맙다고 하고, 거스름돈은 가지라고 하고, 좋은 하루 보내라고 하세요.',
   '[{"all":["keep the change"]},{"all":["good one"]},{"all":["good day"]},{"all":["great day"]}]',
   'Thanks, Nina. Keep the change. Have a good one!',
   '["Could I get the check, please?","I''ll have it done by end of day.","Can you add me to the repo?"]',
   '["Leave the change as a tip and say goodbye.","Key words: keep the change, have a good one"]', '["거스름돈을 팁으로 남기고 작별 인사를 하세요.","핵심 단어: keep the change, have a good one"]',
   'nina', 'You too, Derek! Don''t work too hard.', '데릭도요! 너무 무리하지 말고요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d1_coffee.the_usual', 'dk_d1_coffee', 'The usual, please.', '늘 먹던 걸로 주세요.', 'What a regular says instead of naming the order.', '단골이 주문 내용을 말하는 대신 쓰는 표현입니다.', 'food'),
  ('dk_d1_coffee.coming_right_up', 'dk_d1_coffee', 'Coming right up!', '바로 나와요!', 'Said by staff: your order will be ready very soon.', '직원이 주문한 것이 곧 나온다고 할 때 씁니다.', 'food'),
  ('dk_d1_coffee.room_for_cream', 'dk_d1_coffee', 'with room for cream', '크림 넣을 자리를 남겨서', 'Ask for this so the cup is not filled to the top.', '컵을 끝까지 채우지 말아 달라고 할 때 씁니다.', 'food'),
  ('dk_d1_coffee.cant_complain', 'dk_d1_coffee', 'Can''t complain.', '그럭저럭 괜찮아요.', 'A modest answer to "How''s it going?": things are fine.', '"How''s it going?"에 대한 겸손한 대답으로, 괜찮다는 뜻입니다.', 'small-talk'),
  ('dk_d1_coffee.im_good', 'dk_d1_coffee', 'I''m good, thanks.', '괜찮아요, 됐어요.', 'A polite "no, thank you" when someone offers you something.', '누가 무언가를 권할 때 정중히 사양하는 말입니다.', 'small-talk'),
  ('dk_d1_coffee.cut_back_on', 'dk_d1_coffee', 'I''m trying to cut back on sweets.', '단것을 줄이려는 중이에요.', '"Cut back on" = have less of something (sugar, coffee, spending).', 'cut back on은 설탕·커피·지출 같은 것을 줄인다는 뜻입니다.', 'food'),
  ('dk_d1_coffee.on_the_house', 'dk_d1_coffee', 'The next one''s on the house.', '다음 잔은 가게에서 드려요.', '"On the house" = free, paid for by the shop.', 'on the house는 가게가 내는 것, 곧 공짜라는 뜻입니다.', 'food');

-- dk_d1_buddy: Maya has a favor to ask

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_buddy', 1, 'maya',
   'Monday morning. Maya waves at you from her office door with a checklist in her hand.', '월요일 아침입니다. 마야가 체크리스트를 든 채 사무실 문 앞에서 손짓합니다.',
   'Morning, Derek. Got a minute? I have a favor to ask.', 'Say sure, and ask what is up.', '그럼요라고 하고, 무슨 일인지 물어보세요.',
   '[{"all":["what is up"]},{"all":["what do you need"]},{"any":["sure","absolutely"]},{"all":["of course"]}]',
   'Sure, I''ve got a few minutes. What''s up?',
   '["Sorry, I left my badge at home.","No, I''ll have the soup instead.","It''s supposed to rain on Wednesday."]',
   '["Show you have time, then ask what she needs.","Key words: sure, what''s up"]', '["시간이 있다고 하고, 무엇이 필요한지 물어보세요.","핵심 단어: sure, what''s up"]',
   'maya', 'Our new developer, Jun, starts today. I''d like you to be his onboarding buddy.', '새 개발자 준이 오늘 입사해요. 당신이 온보딩 버디를 맡아 주면 좋겠어요.'),
  ('dk_d1_buddy', 2, 'maya',
   'She turns her laptop so you can see the onboarding checklist.', '그녀가 노트북을 돌려 온보딩 체크리스트를 보여 줍니다.',
   'It means showing him the ropes for the first few weeks: the setup, the codebase, how we work. Are you up for it?', 'Say you would be happy to, and ask about his background.', '기꺼이 하겠다고 하고, 그의 경력을 물어보세요.',
   '[{"all":["happy to"]},{"all":["glad to"]},{"all":["love to"]},{"any":["background","experience"]},{"all":["count me in"]}]',
   'I''d be happy to. What''s his background?',
   '["I''d rather take the stairs. Where is the elevator?","I''d like a refill. Is the coffee fresh?","I''d better go. What time is the bus?"]',
   '["Accept warmly with \\"I''d be happy to.\\"","Key words: happy to, background"]', '["\\"I''d be happy to.\\"로 흔쾌히 수락하세요.","핵심 단어: happy to, background"]',
   'maya', 'Three years of backend work in Seoul. This is his first job in the US, so a lot will be new to him.', '서울에서 백엔드 개발을 3년 했어요. 미국에서는 첫 직장이라 낯선 게 많을 거예요.'),
  ('dk_d1_buddy', 3, 'maya',
   'Maya knows your sprint is already full.', '마야는 당신의 스프린트가 이미 꽉 찼다는 것을 압니다.',
   'I know you''re busy with the checkout rebuild. Do you have the bandwidth for this?', 'Say you can make time, but you may need to push one of your tickets to the next sprint.', '시간을 낼 수 있지만, 티켓 하나를 다음 스프린트로 미뤄야 할 수도 있다고 하세요.',
   '[{"all":["make time"]},{"all":["push"],"any":["ticket","tickets","sprint"]},{"all":["bandwidth"]}]',
   'I can make time, but I might need to push one of my tickets to the next sprint.',
   '["I can drive, but I might need to stop for gas.","I can come on Saturday, but I might be a little late.","I can pay by card, but I might need a receipt."]',
   '["Say yes, and name the cost honestly.","Key words: make time, push a ticket"]', '["하겠다고 하되, 그 대가를 솔직히 말하세요.","핵심 단어: make time, push a ticket"]',
   'maya', 'That''s reasonable. Tell Priya which one, and I''ll back you up.', '그럴 만해요. 어느 티켓인지 프리야에게 말해요. 제가 힘을 실어 줄게요.'),
  ('dk_d1_buddy', 4, 'maya',
   'She checks a box on her list.', '그녀가 목록의 칸 하나에 체크합니다.',
   'One more thing. When you review his first pull request, be kind but honest, okay?', 'Say of course, and that you will check in with him every day this week.', '물론이라고 하고, 이번 주에는 매일 그를 살피겠다고 하세요.',
   '[{"all":["check in"]},{"all":["checking in"]},{"all":["every day"]}]',
   'Of course. I''ll check in with him every day this week.',
   '["Of course. I''ll check out the farmers market this weekend.","Of course. I''ll check the weather before I leave.","Of course. I''ll check my bag at the counter."]',
   '["\\"Check in with someone\\" = talk briefly to see how they are doing.","Key words: check in with him, every day"]', '["check in with someone은 잘 지내는지 잠깐 이야기해 본다는 뜻입니다.","핵심 단어: check in with him, every day"]',
   'maya', 'Perfect. Let me know if you have any questions.', '좋아요. 궁금한 게 있으면 말해 줘요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d1_buddy.got_a_minute', 'dk_d1_buddy', 'Got a minute?', '잠깐 시간 돼요?', 'A casual way to start a short talk at work.', '직장에서 짧은 이야기를 시작할 때 편하게 쓰는 말입니다.', 'office'),
  ('dk_d1_buddy.favor_to_ask', 'dk_d1_buddy', 'I have a favor to ask.', '부탁이 하나 있어요.', 'Said before asking someone to do something for you.', '무언가를 부탁하기 전에 하는 말입니다.', 'office'),
  ('dk_d1_buddy.show_the_ropes', 'dk_d1_buddy', 'show him the ropes', '그에게 일하는 요령을 알려 주다', 'Teach a newcomer how things are done.', '새로 온 사람에게 일하는 방법을 가르쳐 준다는 뜻입니다.', 'office'),
  ('dk_d1_buddy.up_for_it', 'dk_d1_buddy', 'Are you up for it?', '해 볼 마음 있어요?', 'Asks if someone is willing and has the energy to do something.', '할 마음과 여력이 있는지 묻는 말입니다.', 'office'),
  ('dk_d1_buddy.happy_to', 'dk_d1_buddy', 'I''d be happy to.', '기꺼이 할게요.', 'A warm way to agree to a request.', '부탁을 흔쾌히 받아들이는 말입니다.', 'office'),
  ('dk_d1_buddy.bandwidth', 'dk_d1_buddy', 'Do you have the bandwidth for this?', '이걸 할 여력이 있어요?', '"Bandwidth" = time and energy for more work.', 'bandwidth는 일을 더 맡을 시간과 여력을 뜻합니다.', 'office'),
  ('dk_d1_buddy.back_you_up', 'dk_d1_buddy', 'I''ll back you up.', '제가 힘을 실어 줄게요.', '"Back someone up" = support them, especially in front of others.', 'back someone up은 특히 다른 사람들 앞에서 편들어 준다는 뜻입니다.', 'office'),
  ('dk_d1_buddy.check_in_with', 'dk_d1_buddy', 'I''ll check in with him every day.', '매일 그를 살펴볼게요.', 'A short, friendly talk to see how someone is doing.', '잘 지내는지 짧게 살펴보는 것을 말합니다.', 'office');

-- dk_d1_standup: Your status update

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_standup', 1, 'priya',
   'The team stands around the screen in the meeting room. Jun, the new hire, has just introduced himself.', '팀이 회의실 화면 앞에 둘러서 있습니다. 신입 준이 방금 자기소개를 마쳤습니다.',
   'Okay, let''s keep going. Derek, you''re up. Where are we with the checkout API?', 'Say that last week you wrapped up the checkout API changes and they are in review now.', '지난주에 결제 API 수정을 마무리했고 지금 리뷰 중이라고 하세요.',
   '[{"all":["wrapped up"]},{"all":["in review"]},{"any":["finished","merged"]}]',
   'Last week I wrapped up the checkout API changes. They''re in review now.',
   '["Last week I went camping with my family.","Last week the bus was late every day.","Last week I tried the new taco place."]',
   '["Say what is done and where it is now.","Key words: wrapped up, in review"]', '["무엇을 끝냈고 지금 어떤 상태인지 말하세요.","핵심 단어: wrapped up, in review"]',
   'priya', 'Nice. One less thing on the board.', '좋아요. 보드에서 하나 줄었네요.'),
  ('dk_d1_standup', 2, 'priya',
   'Priya moves your card on the board.', '프리야가 보드에서 당신의 카드를 옮깁니다.',
   'And what''s on your plate today?', 'Say you are picking up the saved cards ticket and helping Jun get set up.', '저장된 카드 티켓을 새로 맡고, 준의 환경 설정을 돕는다고 하세요.',
   '[{"all":["picking up"]},{"all":["working on"]},{"all":["set up"]},{"all":["helping","jun"]}]',
   'Today I''m picking up the saved cards ticket and helping Jun get set up.',
   '["Today I''m having the club sandwich.","Today is Monday, I think.","Today I''m taking the early bus home."]',
   '["\\"Pick up a ticket\\" = start working on it.","Key words: picking up, get set up"]', '["pick up a ticket은 그 일을 시작한다는 뜻입니다.","핵심 단어: picking up, get set up"]',
   'priya', 'Great. Thanks for looking after him.', '좋아요. 준을 챙겨 줘서 고마워요.'),
  ('dk_d1_standup', 3, 'priya',
   'She looks up from her laptop.', '그녀가 노트북에서 고개를 듭니다.',
   'Any blockers?', 'Say you are still waiting on the API keys from Summit Retail, and ask her to follow up with them.', '서밋 리테일의 API 키를 아직 기다리고 있다고 하고, 그쪽에 확인해 달라고 부탁하세요.',
   '[{"all":["waiting on"]},{"all":["waiting for"]},{"all":["follow up"]},{"all":["blocked"]}]',
   'Just one. I''m still waiting on the API keys from Summit Retail. Could you follow up with them?',
   '["Just one. I''m still hungry. Could you pass the salsa?","Just one. I lost my umbrella on the bus.","None. Everything is on sale this week."]',
   '["Name what you are waiting on, and ask for help.","Key words: waiting on, follow up"]', '["무엇을 기다리는지 말하고 도움을 청하세요.","핵심 단어: waiting on, follow up"]',
   'priya', 'I''ll ping Greg''s team right after this.', '끝나자마자 그레그 팀에 연락할게요.'),
  ('dk_d1_standup', 4, 'priya',
   'The standup is at minute twelve. Priya remembers one more thing.', '스탠드업이 12분째입니다. 프리야가 한 가지를 더 떠올립니다.',
   'Oh, and Summit Retail asked about gift card support. Derek, how big is that? Can we talk it through now?', 'Suggest taking it offline so you do not hold up the standup.', '스탠드업이 길어지지 않게 따로 이야기하자고 제안하세요.',
   '[{"all":["offline"]},{"all":["after standup"]},{"all":["after the standup"]},{"any":["separately"]}]',
   'Let''s take that offline. I don''t want to hold up the standup.',
   '["Let''s take the stairs. The elevator is acting up.","Let''s take a break and get some coffee.","Let''s take the bus downtown."]',
   '["\\"Take it offline\\" = discuss it later, outside this meeting.","Key words: take that offline"]', '["take it offline은 이 회의 밖에서 나중에 이야기하자는 뜻입니다.","핵심 단어: take that offline"]',
   'priya', 'Good call. I''ll put thirty minutes on our calendars for tomorrow.', '좋은 판단이에요. 내일 30분 일정을 잡아 둘게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d1_standup.where_are_we', 'dk_d1_standup', 'Where are we with the checkout API?', '결제 API는 어디까지 됐어요?', '"Where are we with …?" asks for the status of a piece of work.', '"Where are we with …?"는 일의 진행 상황을 묻는 말입니다.', 'meeting'),
  ('dk_d1_standup.wrapped_up', 'dk_d1_standup', 'I wrapped up the API changes.', 'API 수정을 마무리했어요.', '"Wrap up" = finish.', 'wrap up은 끝내다라는 뜻입니다.', 'meeting'),
  ('dk_d1_standup.in_review', 'dk_d1_standup', 'They''re in review now.', '지금 리뷰 중이에요.', 'The code is waiting for a teammate to review it.', '코드가 동료의 리뷰를 기다리는 상태입니다.', 'meeting'),
  ('dk_d1_standup.picking_up', 'dk_d1_standup', 'I''m picking up the saved cards ticket.', '저장된 카드 티켓을 맡아서 시작해요.', '"Pick up a ticket" = take it and start working on it.', 'pick up a ticket은 티켓을 맡아 일을 시작한다는 뜻입니다.', 'meeting'),
  ('dk_d1_standup.waiting_on', 'dk_d1_standup', 'I''m still waiting on the API keys.', '아직 API 키를 기다리고 있어요.', '"Waiting on" something = you cannot go on until you get it.', 'waiting on은 그것을 받아야 일을 계속할 수 있다는 뜻입니다.', 'meeting'),
  ('dk_d1_standup.follow_up', 'dk_d1_standup', 'Could you follow up with them?', '그쪽에 다시 확인해 주시겠어요?', '"Follow up" = contact someone again about something still open.', 'follow up은 아직 끝나지 않은 일로 다시 연락하는 것입니다.', 'meeting'),
  ('dk_d1_standup.take_offline', 'dk_d1_standup', 'Let''s take that offline.', '그건 따로 이야기하죠.', 'Moves a side topic out of the meeting so it can end on time.', '곁가지 주제를 회의 밖으로 돌려 회의를 제때 끝내게 합니다.', 'meeting'),
  ('dk_d1_standup.hold_up', 'dk_d1_standup', 'I don''t want to hold up the standup.', '스탠드업을 붙잡아 두고 싶지 않아요.', '"Hold up" = delay.', 'hold up은 지연시키다라는 뜻입니다.', 'meeting');

-- dk_d1_welcome: Welcoming the new hire

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_welcome', 1, 'jun',
   'A young man is unpacking a new laptop at the desk next to yours. You stuck a "Welcome!" note on his monitor this morning.', '당신 옆자리에서 한 청년이 새 노트북을 꺼내고 있습니다. 오늘 아침 당신이 그의 모니터에 "Welcome!" 쪽지를 붙여 두었습니다.',
   'Oh, hi. Excuse me, are you Derek? Maya said I should come find you.', 'Introduce yourself and welcome him to the team.', '자기소개를 하고 팀에 온 것을 환영하세요.',
   '[{"all":["welcome"]}]',
   'That''s me. You must be Jun. Welcome to the team!',
   '["That''s me. I ordered the large cold brew.","That''s mine. I left it on the bus.","That''s me. I have a reservation for two."]',
   '["Confirm who you are, then welcome him.","Key words: you must be Jun, welcome"]', '["당신이 맞다고 하고 환영하세요.","핵심 단어: you must be Jun, welcome"]',
   'jun', 'Thank you! Nice to meet you. I''m a little nervous, honestly.', '감사합니다! 만나서 반갑습니다. 사실 조금 긴장돼요.'),
  ('dk_d1_welcome', 2, 'jun',
   'Jun opens the laptop. The screen is still empty.', '준이 노트북을 엽니다. 화면은 아직 텅 비어 있습니다.',
   'I haven''t set up my dev environment yet. Where should I start?', 'Offer to walk him through it, starting with the README.', 'README부터 시작해서 차근차근 알려 주겠다고 하세요.',
   '[{"all":["walk you through"]},{"any":["readme"]},{"all":["setup guide"]},{"all":["show you"]}]',
   'No worries. Let me walk you through it. Start with the README in the repo.',
   '["No worries. Let me get the check.","No worries. The diner opens at six thirty.","No worries. Let me hold the elevator for you."]',
   '["\\"Walk someone through\\" = explain step by step.","Key words: walk you through, README"]', '["walk someone through는 단계별로 설명해 준다는 뜻입니다.","핵심 단어: walk you through, README"]',
   'jun', 'Great. I''ll clone the repo right now.', '좋아요. 지금 바로 저장소를 클론할게요.'),
  ('dk_d1_welcome', 3, 'jun',
   'The setup script prints a wall of red text. Jun''s face falls.', '설치 스크립트가 빨간 글씨를 가득 쏟아 냅니다. 준의 얼굴이 어두워집니다.',
   'Um, the tests are failing on my machine. Did I break something?', 'Reassure him: he did not break anything, and it happens to everybody on day one.', '안심시켜 주세요. 망가뜨린 건 없고, 첫날에는 누구나 겪는 일이라고요.',
   '[{"all":["happens to"]},{"any":["worry","worries"]},{"all":["did not break"]},{"all":["not your fault"]}]',
   'Don''t worry, you didn''t break anything. It happens to everybody on day one.',
   '["Yes, you should call your landlord right away.","Yes, the bus is always late on Mondays.","You should order the pancakes instead."]',
   '["Tell him it is normal and not his fault.","Key words: don''t worry, happens to everybody"]', '["흔한 일이고 그의 잘못이 아니라고 말해 주세요.","핵심 단어: don''t worry, happens to everybody"]',
   'jun', 'That''s a relief. I thought I broke the build on my first day.', '다행이네요. 첫날부터 빌드를 깨뜨린 줄 알았어요.'),
  ('dk_d1_welcome', 4, 'jun',
   'You fix the missing setting together. The tests turn green.', '빠진 설정을 함께 고칩니다. 테스트가 초록색으로 바뀝니다.',
   'Sorry, I have so many questions. I don''t want to bother you.', 'Tell him he is not bothering you, and to ping you anytime.', '전혀 방해가 아니라고 하고, 언제든 메시지를 보내라고 하세요.',
   '[{"all":["ping me"]},{"any":["anytime","dumb","stupid"]},{"all":["any time"]},{"all":["not bothering"]}]',
   'You''re not bothering me. Just ping me anytime. There are no dumb questions.',
   '["You''re not allowed to park here.","You''re next in line. Step forward, please.","You''re going to need a bigger bag."]',
   '["Make it safe to ask: \\"ping me\\", \\"no dumb questions\\".","Key words: ping me anytime, no dumb questions"]', '["편하게 물어볼 수 있게 해 주세요. \\"ping me\\", \\"no dumb questions\\".","핵심 단어: ping me anytime, no dumb questions"]',
   'jun', 'Thanks, Derek. That really helps.', '고마워요, 데릭. 정말 도움이 돼요.'),
  ('dk_d1_welcome', 5, 'jun',
   'Jun opens the ticket board.', '준이 티켓 보드를 엽니다.',
   'What should I work on first, once everything is running?', 'Tell him to start with a small bug fix and open a pull request, which you will review.', '작은 버그 수정부터 시작해서 풀 리퀘스트를 올리면 당신이 리뷰하겠다고 하세요.',
   '[{"all":["pull request"]},{"all":["small"],"any":["bug","ticket","fix","issue"]},{"any":["review"]}]',
   'Start with a small bug fix and open a pull request. I''ll review it first thing tomorrow.',
   '["Start with the soup, and then order the burger.","Start at the bus stop and walk two blocks north.","Start with your photo ID and a signature."]',
   '["Give him a small first task and promise a review.","Key words: small bug fix, pull request, review"]', '["작은 첫 과제를 주고 리뷰를 약속하세요.","핵심 단어: small bug fix, pull request, review"]',
   'jun', 'Sounds good. I''ll have it up by tonight.', '좋아요. 오늘 밤까지 올릴게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d1_welcome.you_must_be', 'dk_d1_welcome', 'You must be Jun.', '준이군요.', 'A friendly way to greet someone you were expecting.', '기다리던 사람을 반갑게 맞이하는 말입니다.', 'office'),
  ('dk_d1_welcome.welcome_to_team', 'dk_d1_welcome', 'Welcome to the team!', '팀에 온 걸 환영해요!', 'Said to a new teammate on the first day.', '새 팀원에게 첫날 하는 말입니다.', 'office'),
  ('dk_d1_welcome.walk_you_through', 'dk_d1_welcome', 'Let me walk you through it.', '차근차근 알려 줄게요.', '"Walk someone through" = explain something step by step.', 'walk someone through는 단계별로 설명해 준다는 뜻입니다.', 'office'),
  ('dk_d1_welcome.didnt_break', 'dk_d1_welcome', 'You didn''t break anything.', '망가뜨린 거 없어요.', 'Reassures someone who thinks a problem is their fault.', '문제가 자기 탓이라고 생각하는 사람을 안심시킵니다.', 'office'),
  ('dk_d1_welcome.thats_a_relief', 'dk_d1_welcome', 'That''s a relief.', '다행이네요.', 'Said when a worry turns out to be nothing.', '걱정하던 일이 별것 아니었을 때 하는 말입니다.', 'small-talk'),
  ('dk_d1_welcome.ping_me_anytime', 'dk_d1_welcome', 'Just ping me anytime.', '언제든 메시지 줘요.', '"Ping" = send a short chat message.', 'ping은 짧은 채팅 메시지를 보낸다는 뜻입니다.', 'office'),
  ('dk_d1_welcome.no_dumb_questions', 'dk_d1_welcome', 'There are no dumb questions.', '바보 같은 질문은 없어요.', 'Encourages a newcomer to ask anything.', '새로 온 사람이 무엇이든 묻도록 북돋는 말입니다.', 'office'),
  ('dk_d1_welcome.first_thing', 'dk_d1_welcome', 'I''ll review it first thing tomorrow.', '내일 아침에 제일 먼저 리뷰할게요.', '"First thing" = before anything else in the morning.', 'first thing은 아침에 다른 일보다 먼저라는 뜻입니다.', 'office');

-- dk_d2_review: Talking through the review

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_review', 1, 'jun',
   'You roll your chair over to Jun''s desk with your coffee. He has your review open on his screen.', '커피를 들고 의자를 굴려 준의 자리로 갑니다. 그의 화면에 당신의 리뷰가 열려 있습니다.',
   'Good morning. I saw your comments on my pull request. There are twelve of them. Is it that bad?', 'Reassure him: it is a solid first pull request, and most of your comments are just nits.', '안심시켜 주세요. 첫 풀 리퀘스트로 탄탄하고, 코멘트 대부분은 사소한 지적이라고요.',
   '[{"any":["nits","nit","nitpicks"]},{"all":["solid"]},{"all":["good start"]},{"any":["minor"]}]',
   'Not at all. It''s a solid first pull request. Most of my comments are just nits.',
   '["Not at all. The diner is right around the corner.","Yes, the rent is due on the first.","Not really. I usually take the bus."]',
   '["Start with what is good. A \\"nit\\" is a tiny, optional fix.","Key words: solid, just nits"]', '["좋은 점부터 말하세요. nit은 아주 사소한, 선택적인 수정입니다.","핵심 단어: solid, just nits"]',
   'jun', 'Oh, good. I was worried all night.', '아, 다행이에요. 밤새 걱정했어요.'),
  ('dk_d2_review', 2, 'jun',
   'Jun scrolls through the comments.', '준이 코멘트를 쭉 내려 봅니다.',
   'Which comment is the most important one?', 'Explain that the main one is error handling: if the payment call fails, the code swallows the error.', '가장 중요한 건 오류 처리라고 설명하세요. 결제 호출이 실패하면 코드가 오류를 삼켜 버린다고요.',
   '[{"all":["error handling"]},{"any":["swallow","swallowed","swallows"]},{"all":["payment"],"any":["fails","fail","failure"]}]',
   'The main one is error handling. Right now, if the payment call fails, we swallow the error.',
   '["The main one is on Lake Avenue, next to the bank.","The main thing is to tip fifteen to twenty percent.","The main course comes with fries or a salad."]',
   '["Say \\"we\\", not \\"you\\": the problem is in the code, not in him.","Key words: error handling, swallow the error"]', '["you 대신 we를 쓰세요. 문제는 사람이 아니라 코드에 있습니다.","핵심 단어: error handling, swallow the error"]',
   'jun', 'I see. So the user never finds out that it failed.', '그렇군요. 그러면 사용자는 실패한 줄도 모르겠네요.'),
  ('dk_d2_review', 3, 'jun',
   'He opens the file.', '그가 파일을 엽니다.',
   'What should I do instead?', 'Suggest logging the error and showing a friendly message, and ask what he thinks about adding a retry.', '오류를 로그로 남기고 친절한 메시지를 보여 주자고 제안하고, 재시도를 넣는 건 어떻게 생각하는지 물어보세요.',
   '[{"any":["log","logging"]},{"any":["retry"]},{"all":["friendly message"]},{"all":["error message"]}]',
   'I''d suggest logging it and showing the user a friendly message. What do you think about adding one retry?',
   '["I''d suggest the apple pie. It''s the best in town.","What do you think about moving the meeting to two?","I''d take the Number 12 and get off at Lake Avenue."]',
   '["Soften it: \\"I''d suggest …\\", \\"What do you think about …?\\"","Key words: I''d suggest, logging, retry"]', '["\\"I''d suggest …\\", \\"What do you think about …?\\"로 부드럽게 말하세요.","핵심 단어: I''d suggest, logging, retry"]',
   'jun', 'A retry makes sense. I''ll add that.', '재시도가 맞겠네요. 넣을게요.'),
  ('dk_d2_review', 4, 'jun',
   'Jun points at a smaller comment.', '준이 작은 코멘트 하나를 가리킵니다.',
   'And the variable names. Is "data2" really a problem?', 'Say it is a nit, but a clearer name helps the next person who reads the code.', '사소한 지적이지만, 더 분명한 이름이 다음에 코드를 읽을 사람에게 도움이 된다고 하세요.',
   '[{"all":["nit"]},{"any":["clearer","readable","descriptive"]},{"all":["next person"]}]',
   'It''s a nit, but a clearer name helps the next person who reads the code.',
   '["It''s a ten-minute walk, but the bus is faster.","It''s a nice day, but it might cloud over later.","It''s a deal, but only if you buy two."]',
   '["Call it small, and give the reason.","Key words: nit, clearer name"]', '["사소하다고 말하고 이유를 덧붙이세요.","핵심 단어: nit, clearer name"]',
   'jun', 'That''s fair. I''ll rename them.', '맞는 말이에요. 이름을 바꿀게요.'),
  ('dk_d2_review', 5, 'jun',
   'He writes a short to-do list.', '그가 할 일을 짧게 적습니다.',
   'I''ll add a unit test for the failure case, too. Anything else?', 'Say that is it, that you will approve it once the tests pass, and tell him nice work.', '그게 전부라고 하고, 테스트가 통과하면 승인하겠다고 하고, 잘했다고 말해 주세요.',
   '[{"any":["approve"]},{"all":["nice work"]},{"all":["good job"]},{"all":["great job"]},{"all":["looks good"]}]',
   'That''s it. Once the tests pass, I''ll approve it. Nice work, by the way.',
   '["That''s it. Once the rain stops, I''ll mow the lawn.","That''s all. Once you sign here, the room is yours.","That''s it. Once the bus comes, we can go."]',
   '["Close with the next step and a compliment.","Key words: approve, nice work"]', '["다음 단계와 칭찬으로 마무리하세요.","핵심 단어: approve, nice work"]',
   'jun', 'Thank you! I''ll push an update by end of day.', '감사합니다! 오늘 퇴근 전까지 수정해서 올릴게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d2_review.solid', 'dk_d2_review', 'It''s a solid first pull request.', '첫 풀 리퀘스트로 탄탄해요.', '"Solid" = good and reliable. Start feedback with what works.', 'solid는 탄탄하고 믿을 만하다는 뜻입니다. 피드백은 잘된 점부터 시작합니다.', 'office'),
  ('dk_d2_review.just_nits', 'dk_d2_review', 'Most of my comments are just nits.', '제 코멘트는 대부분 사소한 거예요.', 'A nit (nitpick) is a tiny issue. Reviewers write "Nit: …" before optional comments.', 'nit(nitpick)은 아주 사소한 지적입니다. 리뷰어는 선택 사항인 코멘트 앞에 "Nit: …"라고 씁니다.', 'office'),
  ('dk_d2_review.main_one', 'dk_d2_review', 'The main one is error handling.', '가장 중요한 건 오류 처리예요.', 'Tells the listener which point matters most.', '어느 것이 가장 중요한지 알려 줍니다.', 'office'),
  ('dk_d2_review.swallow_error', 'dk_d2_review', 'We swallow the error.', '오류를 삼켜 버려요.', 'The code catches an error and does nothing with it. "We" keeps it from sounding like blame.', '코드가 오류를 잡고도 아무것도 하지 않는다는 뜻입니다. we를 쓰면 탓하는 말로 들리지 않습니다.', 'office'),
  ('dk_d2_review.id_suggest', 'dk_d2_review', 'I''d suggest logging it.', '로그를 남기면 좋겠어요.', '"I''d suggest …" is softer than "You should …".', '"I''d suggest …"는 "You should …"보다 부드럽습니다.', 'office'),
  ('dk_d2_review.what_do_you_think', 'dk_d2_review', 'What do you think about adding one retry?', '재시도를 한 번 넣는 건 어떻게 생각해요?', 'Turns an instruction into a question, so the author decides.', '지시를 질문으로 바꿔 작성자가 결정하게 합니다.', 'office'),
  ('dk_d2_review.once_tests_pass', 'dk_d2_review', 'Once the tests pass, I''ll approve it.', '테스트가 통과하면 승인할게요.', '"Once" = as soon as, after.', 'once는 ~하자마자, ~한 뒤에라는 뜻입니다.', 'office'),
  ('dk_d2_review.nice_work', 'dk_d2_review', 'Nice work, by the way.', '그건 그렇고, 잘했어요.', '"By the way" adds something extra; here, a compliment.', 'by the way는 덧붙이는 말로, 여기서는 칭찬을 더합니다.', 'office');

-- dk_d2_estimate: That is not a two-day job

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_estimate', 1, 'priya',
   'The thirty minutes Priya booked yesterday. She has the roadmap on the big screen.', '어제 프리야가 잡아 둔 30분 회의입니다. 큰 화면에 로드맵이 떠 있습니다.',
   'Thanks for making time. Summit Retail wants gift card support in checkout. I told them it''s probably a two-day job. Does that sound right?', 'Push back politely: say it is more like a week.', '정중히 반대하세요. 일주일은 걸릴 일이라고요.',
   '[{"all":["push back"]},{"all":["more like"]},{"any":["week","optimistic","underestimate"]}]',
   'I''d push back on that. Honestly, it''s more like a week.',
   '["I''d like that to go, please.","That sounds right. Two days is plenty.","I''d ask Tom. He knows where the good coffee is."]',
   '["Disagree with the number, not the person.","Key words: push back, more like a week"]', '["사람이 아니라 숫자에 반대하세요.","핵심 단어: push back, more like a week"]',
   'priya', 'A week? Okay, help me understand.', '일주일요? 알겠어요, 이해할 수 있게 설명해 줘요.'),
  ('dk_d2_estimate', 2, 'priya',
   'Priya pulls up the design. It shows one new field on the payment form.', '프리야가 디자인을 띄웁니다. 결제 양식에 새 입력란 하나가 보입니다.',
   'What makes it so big? It looks like one extra field on the form.', 'Explain that under the hood it touches the legacy payment code, which has no tests.', '내부적으로는 테스트가 없는 레거시 결제 코드를 건드려야 한다고 설명하세요.',
   '[{"any":["legacy"]},{"all":["no tests"]},{"all":["old code"]},{"all":["under the hood"]}]',
   'The form is the easy part. Under the hood, it touches the legacy payment code, and that has no tests.',
   '["The form is in the top drawer at the front desk.","The easy part is finding a place to park.","It looks like rain, so I brought an umbrella."]',
   '["Give the technical reason in plain words.","Key words: under the hood, legacy, no tests"]', '["기술적인 이유를 쉬운 말로 설명하세요.","핵심 단어: under the hood, legacy, no tests"]',
   'priya', 'Ah. The legacy stuff again.', '아. 또 레거시군요.'),
  ('dk_d2_estimate', 3, 'priya',
   'She taps her pen on the table.', '그녀가 펜으로 테이블을 톡톡 칩니다.',
   'I hear you. But Greg is expecting a date. What can I tell him?', 'Propose a timebox: one day for a spike, then a real estimate.', '시간을 정하자고 제안하세요. 하루 동안 사전 조사를 하고 제대로 된 추정치를 주겠다고요.',
   '[{"any":["timebox","timeboxed","spike"]},{"all":["real estimate"]},{"all":["one day"],"any":["estimate","investigate"]}]',
   'Can we timebox it? Give me one day for a spike, and I''ll come back with a real estimate.',
   '["Can we get a table by the window?","Tell him the diner closes at nine thirty.","Give me a large coffee with room for cream."]',
   '["Offer a small, fixed amount of time to find out.","Key words: timebox, spike, real estimate"]', '["알아보는 데 쓸 짧고 정해진 시간을 제안하세요.","핵심 단어: timebox, spike, real estimate"]',
   'priya', 'A one-day spike. I can sell that.', '하루짜리 사전 조사. 그건 설득할 수 있어요.'),
  ('dk_d2_estimate', 4, 'priya',
   'Priya looks at the sprint board. It is full.', '프리야가 스프린트 보드를 봅니다. 꽉 차 있습니다.',
   'And if it really is a week, something has to give. What would you drop?', 'Say it is a trade-off, and that you would move saved cards to the next sprint.', '하나를 얻으면 하나를 내줘야 한다고 하고, 저장된 카드를 다음 스프린트로 옮기겠다고 하세요.',
   '[{"all":["next sprint"]},{"all":["trade off"]},{"any":["tradeoff","deprioritize"]},{"all":["saved cards"]}]',
   'It''s a trade-off. I''d move saved cards to the next sprint.',
   '["I''d drop it off at the front desk.","I''d move the couch closer to the window.","It''s a deal. I''d take two of them."]',
   '["Name what moves out if this moves in.","Key words: trade-off, next sprint"]', '["이 일이 들어오면 무엇이 빠지는지 말하세요.","핵심 단어: trade-off, next sprint"]',
   'priya', 'Okay. I''d rather give him an honest date than a missed one. Thanks for being straight with me.', '알겠어요. 못 지킬 날짜보다 정직한 날짜를 주는 게 낫죠. 솔직하게 말해 줘서 고마워요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d2_estimate.push_back', 'dk_d2_estimate', 'I''d push back on that.', '그건 좀 다르게 생각해요.', 'A polite, professional way to disagree with a plan or number.', '계획이나 숫자에 정중하고 프로답게 반대하는 표현입니다.', 'meeting'),
  ('dk_d2_estimate.more_like', 'dk_d2_estimate', 'It''s more like a week.', '일주일에 더 가까워요.', '"More like" corrects an estimate.', 'more like는 추정치를 바로잡을 때 씁니다.', 'meeting'),
  ('dk_d2_estimate.help_me_understand', 'dk_d2_estimate', 'Help me understand.', '이해할 수 있게 설명해 주세요.', 'Asks for the reasons without sounding like an attack.', '공격적으로 들리지 않게 이유를 묻는 말입니다.', 'meeting'),
  ('dk_d2_estimate.under_the_hood', 'dk_d2_estimate', 'under the hood', '내부적으로는, 겉으로 보이지 않는 곳에서는', 'Inside the system, where users cannot see. From a car''s hood.', '사용자에게 보이지 않는 시스템 내부를 뜻합니다. 자동차 보닛에서 온 말입니다.', 'office'),
  ('dk_d2_estimate.timebox', 'dk_d2_estimate', 'Can we timebox it?', '시간을 정해 놓고 할까요?', '"Timebox" = give a task a fixed amount of time and stop when it is up.', 'timebox는 일에 정해진 시간을 주고 그 시간이 되면 멈추는 것입니다.', 'meeting'),
  ('dk_d2_estimate.spike', 'dk_d2_estimate', 'Give me one day for a spike.', '사전 조사에 하루만 주세요.', 'A spike is a short investigation to learn how big a task is.', 'spike는 일이 얼마나 큰지 알아보는 짧은 조사입니다.', 'meeting'),
  ('dk_d2_estimate.something_has_to_give', 'dk_d2_estimate', 'Something has to give.', '뭔가 하나는 포기해야 해요.', 'We cannot do everything; one thing must be dropped.', '전부 다 할 수는 없으니 하나는 빼야 한다는 뜻입니다.', 'meeting'),
  ('dk_d2_estimate.trade_off', 'dk_d2_estimate', 'It''s a trade-off.', '하나를 얻으면 하나를 내줘야 해요.', 'Getting one thing means giving up another.', '하나를 얻으려면 다른 하나를 포기해야 한다는 뜻입니다.', 'meeting');

-- dk_d2_diner: A regular at the Sunny Side

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_diner', 1, 'rosa',
   'The lunch crowd has not arrived yet. Rosa is already pouring a glass of water at your usual seat.', '점심 손님이 아직 몰리기 전입니다. 로사가 벌써 당신이 늘 앉는 자리에 물을 따르고 있습니다.',
   'Well, look who it is! Hi, hon. Your usual spot at the counter?', 'Say yes, please, and ask what the special is today.', '네라고 하고, 오늘의 스페셜이 뭔지 물어보세요.',
   '[{"any":["special","specials"]}]',
   'Yes, please. What''s the special today?',
   '["Yes, please. Which gate does it leave from?","No, thanks. I''m just waiting for the bus.","Yes, please. Put it on my desk."]',
   '["Diners have a dish of the day called \\"the special\\".","Key words: the special"]', '["다이너에는 the special이라는 오늘의 메뉴가 있습니다.","핵심 단어: the special"]',
   'rosa', 'Patty melt with fries, thirteen ninety-five.', '패티 멜트에 감자튀김, 13달러 95센트예요.'),
  ('dk_d2_diner', 2, 'rosa',
   'She takes the pencil from behind her ear.', '그녀가 귀에 꽂은 연필을 뺍니다.',
   'Or I can put in your usual: turkey club, no mayo.', 'Say you will go with the special, and ask for a side salad instead of the fries.', '스페셜로 하겠다고 하고, 감자튀김 대신 사이드 샐러드를 부탁하세요.',
   '[{"all":["instead of"]},{"any":["swap","substitute"]},{"all":["side salad"]}]',
   'I''ll go with the special. Could I get a side salad instead of the fries?',
   '["I''ll go with the window seat, if that''s okay.","I''ll go home and change first.","Could I get a loaner in the meantime?"]',
   '["Choose with \\"I''ll go with …\\" and swap the side.","Key words: go with, instead of the fries"]', '["\\"I''ll go with …\\"로 고르고 사이드를 바꾸세요.","핵심 단어: go with, instead of the fries"]',
   'rosa', 'Sure thing, hon. Salad it is.', '그럼요. 샐러드로 할게요.'),
  ('dk_d2_diner', 3, 'rosa',
   'Rosa holds up the coffee pot.', '로사가 커피포트를 들어 보입니다.',
   'Coffee while you wait?', 'Say just water is fine, because you have already had two cups today.', '오늘 벌써 두 잔을 마셔서 물이면 된다고 하세요.',
   '[{"any":["water"]},{"all":["iced tea"]}]',
   'Just water is fine, thanks. I''ve already had two cups today.',
   '["Just the receipt, thanks.","Just a trim, thanks.","Just browsing, thanks."]',
   '["Say what you want instead of coffee.","Key words: just water"]', '["커피 대신 원하는 것을 말하세요.","핵심 단어: just water"]',
   'rosa', 'Smart. Be right back.', '현명하네요. 금방 올게요.'),
  ('dk_d2_diner', 4, 'rosa',
   'You clean your plate. Rosa comes by with the pie menu.', '접시를 깨끗이 비웠습니다. 로사가 파이 메뉴를 들고 옵니다.',
   'How was everything? Did you save room for pie?', 'Say it hit the spot, but you are stuffed, and ask for just the check.', '딱 좋았지만 배가 너무 부르다고 하고, 계산서만 달라고 하세요.',
   '[{"any":["check","bill"]},{"all":["hit the spot"]},{"any":["stuffed"]}]',
   'It really hit the spot, but I''m stuffed. Just the check, please.',
   '["It was closed, so I came here.","I''m starving. What do you recommend?","It was delayed, so I missed my connection."]',
   '["Praise the food, say you are full, ask for the check.","Key words: hit the spot, stuffed, the check"]', '["음식을 칭찬하고, 배부르다고 하고, 계산서를 부탁하세요.","핵심 단어: hit the spot, stuffed, the check"]',
   'rosa', 'Here you go, hon. No rush.', '여기 있어요. 천천히 해요.'),
  ('dk_d2_diner', 5, 'rosa',
   'The check says $15.10 with tax. You put a ten, a five and three ones on the counter.', '계산서에는 세금 포함 15.10달러라고 적혀 있습니다. 10달러, 5달러, 1달러 석 장을 카운터에 놓습니다.',
   'Fifteen ten. Whenever you''re ready, hon.', 'Give her eighteen dollars and say you are all set, so she keeps the rest as a tip.', '18달러를 주고 거스름돈은 필요 없다고 하세요. 나머지는 팁입니다.',
   '[{"all":["all set"]},{"all":["keep the change"]},{"all":["no change"]}]',
   'Here''s eighteen. We''re all set.',
   '["Here''s my boarding pass.","Here''s the pull request I mentioned.","Here''s your umbrella. You left it at the office."]',
   '["\\"We''re all set\\" with cash means: I do not need change.","Key words: all set"]', '["현금을 내며 \\"We''re all set\\"이라고 하면 거스름돈은 필요 없다는 뜻입니다.","핵심 단어: all set"]',
   'rosa', 'Thanks, hon! Tell that new kid at your office to come by.', '고마워요! 사무실에 새로 온 친구한테도 들르라고 해요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d2_diner.look_who_it_is', 'dk_d2_diner', 'Well, look who it is!', '아니, 이게 누구예요!', 'A warm greeting for someone you know well.', '잘 아는 사람을 반갑게 맞이하는 말입니다.', 'small-talk'),
  ('dk_d2_diner.the_special', 'dk_d2_diner', 'What''s the special today?', '오늘의 스페셜은 뭐예요?', 'The special is a dish offered only that day, often at a good price.', 'special은 그날만 파는 메뉴로, 값이 좋은 경우가 많습니다.', 'food'),
  ('dk_d2_diner.go_with', 'dk_d2_diner', 'I''ll go with the special.', '스페셜로 할게요.', '"Go with" = choose.', 'go with는 고르다라는 뜻입니다.', 'food'),
  ('dk_d2_diner.instead_of', 'dk_d2_diner', 'Could I get a side salad instead of the fries?', '감자튀김 대신 사이드 샐러드로 주시겠어요?', 'Most diners let you swap the side.', '다이너 대부분은 사이드를 바꿔 줍니다.', 'food'),
  ('dk_d2_diner.save_room', 'dk_d2_diner', 'Did you save room for pie?', '파이 먹을 배는 남겨 뒀어요?', '"Save room for" = leave space in your stomach for dessert.', 'save room for는 디저트 먹을 배를 남겨 둔다는 뜻입니다.', 'food'),
  ('dk_d2_diner.hit_the_spot', 'dk_d2_diner', 'It really hit the spot.', '딱 좋았어요.', 'The food was exactly what you wanted.', '음식이 딱 원하던 것이었다는 뜻입니다.', 'food'),
  ('dk_d2_diner.stuffed', 'dk_d2_diner', 'I''m stuffed.', '배가 너무 불러요.', 'Very full. Casual.', '아주 배부르다는 편한 표현입니다.', 'food'),
  ('dk_d2_diner.all_set', 'dk_d2_diner', 'We''re all set.', '이걸로 됐어요. (거스름돈은 괜찮아요.)', 'When you pay cash, it tells the server to keep the change as the tip.', '현금으로 낼 때 거스름돈을 팁으로 가지라는 뜻이 됩니다.', 'food');

-- dk_d3_one_on_one: Where do you go from here?

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_one_on_one', 1, 'maya',
   'Rain taps on the window of Maya''s office. She closes her laptop and turns to you.', '마야의 사무실 창문에 빗방울이 부딪힙니다. 그녀가 노트북을 덮고 당신을 봅니다.',
   'So, six years at Seaside. Where do you see yourself going from here?', 'Say you are interested in the tech lead track.', '테크 리드 트랙에 관심이 있다고 하세요.',
   '[{"all":["tech lead"]},{"all":["technical lead"]},{"all":["lead"],"any":["team","role","track"]}]',
   'I''ve been thinking about that. I''m interested in the tech lead track.',
   '["I''ve been thinking about lunch. I''m in the mood for tacos.","I see myself taking the bus home today.","I''m going to the hardware store on Saturday."]',
   '["Name the role you want with \\"I''m interested in …\\".","Key words: interested in, tech lead track"]', '["\\"I''m interested in …\\"으로 원하는 역할을 말하세요.","핵심 단어: interested in, tech lead track"]',
   'maya', 'I was hoping you''d say that.', '그렇게 말해 주길 바랐어요.'),
  ('dk_d3_one_on_one', 2, 'maya',
   'Maya leans back in her chair.', '마야가 의자에 등을 기댑니다.',
   'What draws you to it? You''d write less code, you know.', 'Say you enjoy mentoring, and you would like more of a say in technical decisions.', '멘토링이 즐겁고, 기술적인 결정에 더 목소리를 내고 싶다고 하세요.',
   '[{"any":["mentoring","mentor"]},{"all":["technical decisions"]},{"all":["a say"]},{"any":["architecture"]}]',
   'I know. But I really enjoy mentoring, and I''d like more of a say in our technical decisions.',
   '["I know. But I really enjoy the pie at the diner.","I know. But parking downtown is a nightmare.","I know. But my lawn needs mowing this weekend."]',
   '["Give your reasons: what you enjoy and what you want.","Key words: mentoring, a say in decisions"]', '["이유를 말하세요. 무엇이 즐겁고 무엇을 원하는지.","핵심 단어: mentoring, a say in decisions"]',
   'maya', 'It shows. Jun already told me how much you''ve helped him.', '눈에 보여요. 준이 벌써 당신이 얼마나 도와줬는지 말하더군요.'),
  ('dk_d3_one_on_one', 3, 'maya',
   'She chooses her words carefully.', '그녀가 조심스럽게 말을 고릅니다.',
   'To be candid, there''s one gap. You tend to take everything on yourself. A lead has to delegate.', 'Accept the feedback: say that is fair, and that delegating is something you need to work on.', '피드백을 받아들이세요. 맞는 말이고, 일을 맡기는 건 당신이 노력해야 할 부분이라고요.',
   '[{"all":["fair"]},{"all":["work on"]},{"all":["working on"]},{"any":["delegate","delegating"]}]',
   'That''s fair. Delegating is something I need to work on.',
   '["That''s far. I''d rather take a cab.","That''s fine. I''ll have the soup instead.","That''s mine. I left it in the meeting room."]',
   '["Do not argue. Agree, and name what you will improve.","Key words: that''s fair, work on"]', '["반박하지 말고, 동의한 뒤 무엇을 고칠지 말하세요.","핵심 단어: that''s fair, work on"]',
   'maya', 'Knowing it is half the battle.', '아는 것만으로도 절반은 된 거예요.'),
  ('dk_d3_one_on_one', 4, 'maya',
   'Maya opens her notes.', '마야가 메모를 엽니다.',
   'So what would help you get there?', 'Ask to take the lead on the gift card project as a stretch assignment.', '도전적인 과제로 기프트 카드 프로젝트를 이끌어 보고 싶다고 하세요.',
   '[{"all":["take the lead"]},{"all":["lead"],"any":["project","gift"]},{"any":["stretch"]},{"all":["run point"]}]',
   'I''d like to take the lead on the gift card project. It would be a good stretch assignment.',
   '["I''d like to take the rest of this to go.","I''d like to take Friday off for a dentist appointment.","I''d like a window seat, if you have one."]',
   '["Ask for a concrete chance to practice.","Key words: take the lead, stretch assignment"]', '["연습할 구체적인 기회를 요청하세요.","핵심 단어: take the lead, stretch assignment"]',
   'maya', 'I like it. Put together a one-page plan, and we''ll revisit this next month.', '좋아요. 한 장짜리 계획을 만들어 봐요. 다음 달에 다시 이야기하죠.'),
  ('dk_d3_one_on_one', 5, 'maya',
   'She writes a note and looks at the clock. Standup is soon.', '그녀가 메모를 하고 시계를 봅니다. 곧 스탠드업입니다.',
   'Anything else on your mind?', 'Ask what it would take to get to the next level.', '다음 단계로 올라가려면 무엇이 필요한지 물어보세요.',
   '[{"all":["next level"]},{"all":["what would it take"]},{"any":["promotion","promoted"]}]',
   'Just one thing. What would it take to get to the next level?',
   '["Just one thing. What time does the market close?","Just one bag, thanks. Paper is fine.","Just a small coffee. What do I owe you?"]',
   '["Ask \\"What would it take to …?\\"","Key words: what would it take, next level"]', '["\\"What would it take to …?\\"로 물어보세요.","핵심 단어: what would it take, next level"]',
   'maya', 'Lead one project end to end, and show me you can delegate. Let me know if you have any questions.', '프로젝트 하나를 처음부터 끝까지 이끌고, 일을 맡길 줄 안다는 걸 보여 줘요. 궁금한 게 있으면 말해 줘요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d3_one_on_one.see_yourself', 'dk_d3_one_on_one', 'Where do you see yourself going from here?', '앞으로 어떤 방향으로 가고 싶어요?', 'A manager''s question about your career goals.', '매니저가 커리어 목표를 물을 때 하는 말입니다.', 'office'),
  ('dk_d3_one_on_one.tech_lead_track', 'dk_d3_one_on_one', 'I''m interested in the tech lead track.', '테크 리드 트랙에 관심이 있어요.', 'A "track" is a career path. A tech lead guides a team''s technical work.', 'track은 커리어 경로입니다. 테크 리드는 팀의 기술적인 일을 이끕니다.', 'office'),
  ('dk_d3_one_on_one.a_say', 'dk_d3_one_on_one', 'I''d like more of a say in our technical decisions.', '기술적인 결정에 더 목소리를 내고 싶어요.', '"Have a say" = have the right to help decide.', 'have a say는 결정에 참여할 권한이 있다는 뜻입니다.', 'office'),
  ('dk_d3_one_on_one.to_be_candid', 'dk_d3_one_on_one', 'To be candid, there''s one gap.', '솔직히 말하면, 부족한 점이 하나 있어요.', '"To be candid" warns that honest feedback is coming.', 'to be candid는 솔직한 피드백이 나온다는 신호입니다.', 'office'),
  ('dk_d3_one_on_one.need_to_work_on', 'dk_d3_one_on_one', 'Delegating is something I need to work on.', '일을 맡기는 건 제가 노력해야 할 부분이에요.', 'A good way to accept feedback without excuses.', '변명 없이 피드백을 받아들이는 좋은 표현입니다.', 'office'),
  ('dk_d3_one_on_one.stretch_assignment', 'dk_d3_one_on_one', 'a stretch assignment', '역량을 넓혀 주는 도전적인 과제', 'Work a little beyond your current level, to help you grow.', '성장을 위해 지금 수준보다 조금 어려운 일을 말합니다.', 'office'),
  ('dk_d3_one_on_one.next_level', 'dk_d3_one_on_one', 'What would it take to get to the next level?', '다음 단계로 가려면 무엇이 필요할까요?', 'A direct but polite way to ask about promotion.', '승진에 대해 직접적이면서도 정중하게 묻는 표현입니다.', 'office'),
  ('dk_d3_one_on_one.revisit', 'dk_d3_one_on_one', 'We''ll revisit this next month.', '다음 달에 다시 이야기해요.', '"Revisit" = come back to a topic later.', 'revisit은 나중에 그 주제로 돌아온다는 뜻입니다.', 'office');

-- dk_d3_tacos: Taco lunch with Jun

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_tacos', 1, 'jun',
   'It is almost noon, and the rain has let up for a while. Jun is eating crackers at his desk, staring at his screen.', '거의 정오이고 비가 잠시 그쳤습니다. 준이 자리에서 크래커를 먹으며 화면을 들여다보고 있습니다.',
   'Oh, hi, Derek. I was just going to work through lunch.', 'Tell him he needs a break, and invite him to get tacos from the food truck with a few of you.', '좀 쉬어야 한다고 하고, 몇 명이 푸드트럭에 타코를 사러 가는데 같이 가자고 하세요.',
   '[{"any":["tacos","taco"]},{"all":["food truck"]},{"all":["join us"]},{"all":["come with"]}]',
   'Come on, you need a break. A few of us are grabbing tacos from the food truck. Want to join us?',
   '["Come on, the meeting started ten minutes ago.","Good idea. I''ll see you at five, then.","Come in! The door is open."]',
   '["Invite him with \\"Want to join us?\\"","Key words: tacos, food truck, join us"]', '["\\"Want to join us?\\"로 초대하세요.","핵심 단어: tacos, food truck, join us"]',
   'jun', 'Tacos? Sure, I''d love to. Let me grab my wallet.', '타코요? 좋아요, 가고 싶어요. 지갑 가져올게요.'),
  ('dk_d3_tacos', 2, 'jun',
   'You wait in line under the awning of the food truck. Jun studies the menu board.', '푸드트럭 차양 아래에서 줄을 서 있습니다. 준이 메뉴판을 유심히 봅니다.',
   'I''ve never ordered from a food truck. What do you recommend?', 'Recommend the fish tacos, and tell him it is your treat.', '피시 타코를 추천하고, 당신이 사겠다고 하세요.',
   '[{"all":["my treat"]},{"all":["on me"]},{"any":["recommend"]},{"all":["go wrong"]},{"all":["fish tacos"]}]',
   'You can''t go wrong with the fish tacos. And put your wallet away. It''s my treat.',
   '["You can''t park here on weekdays.","You have to take your laptop out of the bag.","You should restart it and try again."]',
   '["Recommend a dish, then offer to pay.","Key words: can''t go wrong with, my treat"]', '["메뉴를 추천한 다음 계산하겠다고 하세요.","핵심 단어: can''t go wrong with, my treat"]',
   'jun', 'Really? Thank you! The next one is on me.', '정말요? 감사합니다! 다음엔 제가 살게요.'),
  ('dk_d3_tacos', 3, 'jun',
   'You eat at a picnic table that is still a little wet.', '아직 조금 젖은 피크닉 테이블에서 먹습니다.',
   'Can I ask you something? At the diner, I never know how much to tip.', 'Give him the rule of thumb: fifteen to twenty percent at sit-down places.', '대략적인 기준을 알려 주세요. 앉아서 먹는 식당에서는 15~20퍼센트라고요.',
   '[{"all":["rule of thumb"]},{"any":["fifteen","15","twenty","20","percent"]},{"all":["sit down"]}]',
   'Rule of thumb: fifteen to twenty percent at sit-down places. At a truck like this, it''s up to you.',
   '["Take the Number 12 and get off at Lake Avenue.","Ask Linda. She handles the pay stubs.","The farmers market is on Saturday mornings."]',
   '["Give a simple rule with numbers.","Key words: rule of thumb, fifteen to twenty percent"]', '["숫자가 들어간 간단한 기준을 알려 주세요.","핵심 단어: rule of thumb, fifteen to twenty percent"]',
   'jun', 'Fifteen to twenty. Got it. I''ll remember that.', '15에서 20. 알겠어요. 기억해 둘게요.'),
  ('dk_d3_tacos', 4, 'jun',
   'Jun finishes his second taco.', '준이 두 번째 타코를 다 먹습니다.',
   'Do you have any plans for the weekend?', 'Say you are having a few friends over for a barbecue, as long as the weather holds.', '날씨만 괜찮으면 친구 몇 명을 집에 불러 바비큐를 할 거라고 하세요.',
   '[{"any":["barbecue","bbq","cookout","grill","grilling"]},{"all":["friends over"]}]',
   'I''m having a few friends over for a barbecue, as long as the weather holds.',
   '["I''m having the soup and half a sandwich.","I have an appointment with IT at one.","I''m flying out on Monday for a client meeting."]',
   '["\\"Have people over\\" = invite them to your home.","Key words: friends over, barbecue"]', '["have people over는 사람들을 집에 초대한다는 뜻입니다.","핵심 단어: friends over, barbecue"]',
   'jun', 'That sounds fun. I hope the rain is gone by then.', '재미있겠네요. 그때까지 비가 그쳤으면 좋겠어요.'),
  ('dk_d3_tacos', 5, 'jun',
   'You walk back to the office. A few drops start to fall again.', '사무실로 걸어 돌아갑니다. 빗방울이 다시 떨어지기 시작합니다.',
   'By the way, thank you for this week. I was really nervous on Monday.', 'Tell him he is doing great and picking things up fast.', '아주 잘하고 있고 빨리 배우고 있다고 말해 주세요.',
   '[{"all":["doing great"]},{"all":["doing well"]},{"all":["doing fine"]},{"all":["picking"],"any":["up"]},{"all":["fast learner"]}]',
   'You''re doing great. You''re picking things up faster than I did.',
   '["You''re in the wrong line. Security is over there.","You''re welcome to try, but the store is closed.","You''re late. The standup started at ten."]',
   '["Encourage him with a specific compliment.","Key words: doing great, picking things up"]', '["구체적인 칭찬으로 격려하세요.","핵심 단어: doing great, picking things up"]',
   'jun', 'That means a lot. Thanks for lunch, Derek!', '큰 힘이 돼요. 점심 잘 먹었어요, 데릭!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d3_tacos.work_through_lunch', 'dk_d3_tacos', 'I was going to work through lunch.', '점심을 거르고 일하려고 했어요.', '"Work through lunch" = keep working and skip the lunch break.', 'work through lunch는 점심시간에 쉬지 않고 일한다는 뜻입니다.', 'office'),
  ('dk_d3_tacos.need_a_break', 'dk_d3_tacos', 'Come on, you need a break.', '에이, 좀 쉬어야죠.', '"Come on" here gently pushes someone to agree.', '여기서 come on은 상대가 따르도록 부드럽게 권하는 말입니다.', 'small-talk'),
  ('dk_d3_tacos.join_us', 'dk_d3_tacos', 'Want to join us?', '같이 갈래요?', 'A casual invitation. Short for "Do you want to join us?"', '편한 초대입니다. "Do you want to join us?"를 줄인 말입니다.', 'small-talk'),
  ('dk_d3_tacos.cant_go_wrong', 'dk_d3_tacos', 'You can''t go wrong with the fish tacos.', '피시 타코는 실패할 일이 없어요.', 'A safe recommendation: it is always good.', '언제 골라도 좋다는 안전한 추천입니다.', 'food'),
  ('dk_d3_tacos.my_treat', 'dk_d3_tacos', 'It''s my treat.', '제가 살게요.', 'You are paying for the other person. Also: "It''s on me."', '상대방 몫까지 내겠다는 뜻입니다. "It''s on me."라고도 합니다.', 'food'),
  ('dk_d3_tacos.friends_over', 'dk_d3_tacos', 'I''m having a few friends over.', '친구 몇 명을 집에 부를 거예요.', '"Have someone over" = invite them to your home.', 'have someone over는 집에 초대한다는 뜻입니다.', 'small-talk'),
  ('dk_d3_tacos.weather_holds', 'dk_d3_tacos', 'as long as the weather holds', '날씨만 계속 괜찮으면', '"The weather holds" = it stays dry and nice.', 'the weather holds는 날씨가 계속 좋다는 뜻입니다.', 'small-talk'),
  ('dk_d3_tacos.picking_things_up', 'dk_d3_tacos', 'You''re picking things up fast.', '빨리 배우고 있어요.', '"Pick up" = learn something by doing it.', 'pick up은 해 보면서 익힌다는 뜻입니다.', 'office');

-- dk_d3_planning: Sprint planning: holding the line

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_planning', 1, 'priya',
   'The whole team is in the meeting room. Rain runs down the windows. Priya has the backlog on the screen.', '팀 전체가 회의실에 있습니다. 창문에 빗물이 흘러내립니다. 프리야가 화면에 백로그를 띄웠습니다.',
   'Okay, sprint planning. First up: gift cards. Derek, how did the spike go?', 'Say it is doable but bigger than it looks: eight points, so you should break it into two tickets.', '할 수는 있지만 보기보다 크다고 하세요. 8포인트이니 티켓 두 개로 나누자고요.',
   '[{"any":["eight","8","split"]},{"all":["break"],"any":["down","up","into"]},{"all":["bigger than"]}]',
   'It''s doable, but it''s bigger than it looks. I''d say eight points, so let''s break it into two tickets.',
   '["It''s walkable, but it''s farther than you think.","It went to voicemail, so I left a message.","I''d say medium rare, with a side of fries."]',
   '["Give the result, the size, and a suggestion.","Key words: doable, eight points, break it into"]', '["결과와 크기, 제안을 말하세요.","핵심 단어: doable, eight points, break it into"]',
   'priya', 'Two tickets. Works for me.', '티켓 두 개. 좋아요.'),
  ('dk_d3_planning', 2, 'priya',
   'Priya drags a ticket to the top. Jun is sitting next to you, taking notes.', '프리야가 티켓 하나를 맨 위로 끌어 올립니다. 준이 옆에 앉아 메모를 하고 있습니다.',
   'Next, the refund bug. I was thinking of giving it to Jun. Is that too much for his first week?', 'Say you think he can handle it, and you will pair with him if he gets stuck.', '그가 해낼 수 있을 것 같고, 막히면 같이 작업하겠다고 하세요.',
   '[{"all":["handle"]},{"any":["pair","pairing"]},{"all":["help him"]},{"all":["he is ready"]}]',
   'I think he can handle it. I''ll pair with him if he gets stuck.',
   '["I think he went to the farmers market.","I think it closes at ten tonight.","I think the elevator is out of order."]',
   '["Show trust in him, and offer a safety net.","Key words: handle it, pair with him"]', '["그를 믿는다는 걸 보이고, 안전망을 제안하세요.","핵심 단어: handle it, pair with him"]',
   'jun', 'Thanks, Derek. I''ll do my best!', '고마워요, 데릭. 최선을 다할게요!'),
  ('dk_d3_planning', 3, 'priya',
   'The sprint is full. Priya scrolls to one more item.', '스프린트가 꽉 찼습니다. 프리야가 항목 하나를 더 찾아 내려갑니다.',
   'One more. Sales wants the export report in this sprint, too. Can we squeeze it in?', 'Push back: the team is at capacity, and if that goes in, something else has to come out.', '반대하세요. 팀에 여유가 없고, 그걸 넣으면 다른 걸 빼야 한다고요.',
   '[{"all":["at capacity"]},{"all":["come out"]},{"all":["something else"]},{"all":["on our plate"]}]',
   'I don''t think so. We''re at capacity. If that goes in, something else has to come out.',
   '["I don''t think so. The bus comes every fifteen minutes.","Sure, I can squeeze in a haircut before lunch.","I don''t think I left it at the diner."]',
   '["Say no with a reason and a choice.","Key words: at capacity, something else has to come out"]', '["이유와 선택지를 들어 거절하세요.","핵심 단어: at capacity, something else has to come out"]',
   'priya', 'I was afraid you''d say that. Okay, it goes to the backlog.', '그렇게 말할 줄 알았어요. 알겠어요, 백로그로 보내죠.'),
  ('dk_d3_planning', 4, 'priya',
   'Priya looks around the table.', '프리야가 테이블을 둘러봅니다.',
   'So what can we commit to?', 'Say the team can commit to the refund bug and the first gift card ticket, and the rest is a stretch goal.', '환불 버그와 첫 번째 기프트 카드 티켓은 약속할 수 있고, 나머지는 도전 목표라고 하세요.',
   '[{"any":["commit"]},{"all":["stretch goal"]},{"any":["stretch"]}]',
   'Let''s commit to the refund bug and the first gift card ticket. The rest is a stretch goal.',
   '["Let''s meet at the Anchor after work.","Let''s order pizza for the whole team.","Let''s take the stairs. It''s only three floors."]',
   '["Separate what is promised from what is a bonus.","Key words: commit to, stretch goal"]', '["약속하는 것과 덤인 것을 구분하세요.","핵심 단어: commit to, stretch goal"]',
   'priya', 'Commit, plus a stretch. Let''s lock it in.', '약속한 것에 도전 목표 하나. 이걸로 확정해요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d3_planning.doable', 'dk_d3_planning', 'It''s doable.', '할 수 있어요.', 'Possible, but it will take some effort.', '가능하지만 노력이 좀 든다는 뜻입니다.', 'meeting'),
  ('dk_d3_planning.bigger_than_it_looks', 'dk_d3_planning', 'It''s bigger than it looks.', '보기보다 커요.', 'Warns that a task hides more work than people expect.', '생각보다 일이 많이 숨어 있다고 알리는 말입니다.', 'meeting'),
  ('dk_d3_planning.break_it_into', 'dk_d3_planning', 'Let''s break it into two tickets.', '티켓 두 개로 나눠요.', '"Break into" = divide into smaller parts.', 'break into는 더 작은 부분으로 나눈다는 뜻입니다.', 'meeting'),
  ('dk_d3_planning.pair_with', 'dk_d3_planning', 'I''ll pair with him if he gets stuck.', '막히면 같이 작업할게요.', '"Pair" = two developers working on one problem together.', 'pair는 개발자 둘이 한 문제를 함께 푸는 것입니다.', 'office'),
  ('dk_d3_planning.squeeze_in', 'dk_d3_planning', 'Can we squeeze it in?', '끼워 넣을 수 있을까요?', '"Squeeze in" = fit something into a full schedule.', 'squeeze in은 꽉 찬 일정에 무언가를 끼워 넣는다는 뜻입니다.', 'meeting'),
  ('dk_d3_planning.has_to_come_out', 'dk_d3_planning', 'If that goes in, something else has to come out.', '그걸 넣으면 다른 걸 빼야 해요.', 'A firm but fair way to protect the team from too much work.', '팀에 일이 넘치지 않게 막는, 단호하지만 공정한 표현입니다.', 'meeting'),
  ('dk_d3_planning.commit_to', 'dk_d3_planning', 'What can we commit to?', '무엇을 약속할 수 있어요?', '"Commit to" = promise to deliver.', 'commit to는 해내겠다고 약속한다는 뜻입니다.', 'meeting'),
  ('dk_d3_planning.stretch_goal', 'dk_d3_planning', 'The rest is a stretch goal.', '나머지는 도전 목표예요.', 'Something you will try to do if there is time, but do not promise.', '시간이 되면 해 보겠지만 약속하지는 않는 목표입니다.', 'meeting');

-- dk_d4_incident: Checkout is down

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d4_incident', 1, 'sam',
   'A gray Thursday morning. Your phone buzzes with an alert from production. You are on call this week, so you head straight to Sam''s room.', '흐린 목요일 아침입니다. 운영 환경 경보로 전화기가 울립니다. 이번 주 온콜 담당이라 곧장 샘의 방으로 갑니다.',
   'Hey, Derek. Your phone''s going off too, huh? What are you seeing?', 'Say you are seeing elevated error rates on checkout, and that it started around nine.', '결제에서 오류율이 높아졌고 아홉 시쯤 시작됐다고 하세요.',
   '[{"all":["error rates"]},{"all":["error rate"]},{"any":["elevated","errors","failing","timeouts"]}]',
   'We''re seeing elevated error rates on checkout. It started around nine.',
   '["We''re seeing a movie on Saturday night.","I''m seeing the dentist at three.","We''re looking for aisle seven."]',
   '["Report what you see and since when.","Key words: elevated error rates, started around"]', '["무엇이 보이는지, 언제부터인지 보고하세요.","핵심 단어: elevated error rates, started around"]',
   'sam', 'Yeah, my dashboard''s all red. Have you tried restarting it? Kidding. Mostly.', '네, 제 대시보드도 온통 빨개요. 재시작은 해 봤어요? 농담이에요. 반쯤은요.'),
  ('dk_d4_incident', 2, 'sam',
   'Sam pulls up the logs on his middle monitor.', '샘이 가운데 모니터에 로그를 띄웁니다.',
   'Did anything go out this morning?', 'Say there have been no deploys since Tuesday, so you can rule out a code change, and ask if anything changed on his end.', '화요일 이후로 배포가 없었으니 코드 변경은 아니라고 하고, 그쪽에서 바뀐 게 있는지 물어보세요.',
   '[{"any":["deploy","deploys","deployed","deployment"]},{"all":["rule out"]},{"all":["on your end"]},{"all":["your side"]}]',
   'No deploys since Tuesday, so we can rule out a code change. Did anything change on your end?',
   '["No, thanks. I already had breakfast.","No, I don''t have a rewards card.","Nothing for me. I''m just waiting for a friend."]',
   '["Rule out one cause, then ask about his side.","Key words: no deploys, rule out, on your end"]', '["원인 하나를 배제하고, 그쪽 상황을 물어보세요.","핵심 단어: no deploys, rule out, on your end"]',
   'sam', 'Let me look. Oh. The certificate on the payment gateway expired at 8:57.', '어디 봐요. 아. 결제 게이트웨이 인증서가 8시 57분에 만료됐네요.'),
  ('dk_d4_incident', 3, 'sam',
   'Customers cannot pay right now. Every minute counts.', '지금 고객들이 결제를 못 하고 있습니다. 1분 1초가 급합니다.',
   'I can renew it, but it takes about twenty minutes to roll out. What do you want to do in the meantime?', 'Say to stop the bleeding first: as a workaround, switch traffic to the backup gateway.', '우선 피해부터 막자고 하세요. 임시방편으로 트래픽을 백업 게이트웨이로 돌리자고요.',
   '[{"any":["workaround","backup","failover"]},{"all":["stop the bleeding"]},{"all":["fail over"]}]',
   'Let''s stop the bleeding first. As a workaround, can you switch traffic to the backup gateway?',
   '["Let''s stop for coffee first. Nina''s cart is still open.","Can you switch seats with me? I''d like the aisle.","Let''s wait for the next bus. This one is full."]',
   '["Reduce the damage now; the real fix can follow.","Key words: stop the bleeding, workaround, backup"]', '["지금은 피해를 줄이고, 제대로 된 수정은 그다음입니다.","핵심 단어: stop the bleeding, workaround, backup"]',
   'sam', 'Switching now. Done. Error rates are dropping.', '지금 돌려요. 됐어요. 오류율이 떨어지고 있어요.'),
  ('dk_d4_incident', 4, 'maya',
   'Maya appears in the doorway with her laptop under her arm.', '마야가 노트북을 옆구리에 끼고 문 앞에 나타납니다.',
   'I just saw the alert. What''s the status? Give me the short version.', 'Give the status: checkout was failing for about forty minutes, it is mitigated now, and you are monitoring it.', '상황을 보고하세요. 결제가 40분쯤 실패했고, 지금은 완화됐고, 지켜보는 중이라고요.',
   '[{"any":["mitigated","mitigation"]},{"any":["monitoring","monitor"]},{"all":["under control"]},{"any":["recovered","recovering"]}]',
   'Short version: checkout was failing for about forty minutes. It''s mitigated now, and we''re monitoring it.',
   '["Short version: I missed the bus and walked.","It''s a long story, but the pie was worth it.","Short answer: paper, not plastic."]',
   '["Impact first, then the current state.","Key words: mitigated, monitoring"]', '["영향을 먼저, 그다음 현재 상태를 말하세요.","핵심 단어: mitigated, monitoring"]',
   'maya', 'Okay. Good.', '알겠어요. 다행이네요.'),
  ('dk_d4_incident', 5, 'maya',
   'Maya opens a new page in her notes.', '마야가 메모장의 새 페이지를 엽니다.',
   'Do we know the root cause?', 'Say the root cause was an expired certificate on the payment gateway, and Sam is renewing it now.', '근본 원인은 결제 게이트웨이의 만료된 인증서였고, 샘이 지금 갱신하고 있다고 하세요.',
   '[{"any":["certificate","cert","expired"]}]',
   'The root cause was an expired certificate on the payment gateway. Sam is renewing it now.',
   '["The cause was a flat tire on the Number 12.","The reason is simple: the market closes at ten.","We don''t know. I was at lunch the whole time."]',
   '["Name the cause and who is fixing it.","Key words: root cause, expired certificate"]', '["원인과 누가 고치고 있는지 말하세요.","핵심 단어: root cause, expired certificate"]',
   'sam', 'Ten more minutes and the new one is live.', '10분만 더 있으면 새 인증서가 적용돼요.'),
  ('dk_d4_incident', 6, 'maya',
   'She looks from Sam to you.', '그녀가 샘을 보다가 당신을 봅니다.',
   'Summit Retail is going to ask about this. What are the next steps?', 'Say you will write up a postmortem by tomorrow, add an alert for expiring certificates, and keep her posted.', '내일까지 사후 분석 보고서를 쓰고, 인증서 만료 경보를 추가하고, 계속 상황을 알리겠다고 하세요.',
   '[{"any":["postmortem","alert","reminder"]},{"all":["post mortem"]},{"all":["posted"]},{"all":["write up"]}]',
   'I''ll write up a postmortem by tomorrow and add an alert for expiring certificates. I''ll keep you posted.',
   '["I''ll write my name on the cup.","I''ll take the stairs and meet you on three.","I''ll have what he''s having."]',
   '["Say what you will do, by when, and promise updates.","Key words: postmortem, alert, keep you posted"]', '["무엇을 언제까지 할지 말하고, 소식을 전하겠다고 약속하세요.","핵심 단어: postmortem, alert, keep you posted"]',
   'maya', 'Perfect. Nicely handled, both of you.', '완벽해요. 두 사람 다 잘 처리했어요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d4_incident.on_call', 'dk_d4_incident', 'I''m on call this week.', '이번 주는 제가 온콜 담당이에요.', 'The on-call person must answer alerts, even at night or on weekends.', '온콜 담당자는 밤이나 주말에도 경보에 대응해야 합니다.', 'office'),
  ('dk_d4_incident.error_rates', 'dk_d4_incident', 'We''re seeing elevated error rates on checkout.', '결제에서 오류율이 높아졌어요.', '"Elevated" = higher than normal. A calm, factual way to report a problem.', 'elevated는 평소보다 높다는 뜻입니다. 문제를 차분하고 사실대로 알리는 표현입니다.', 'office'),
  ('dk_d4_incident.rule_out', 'dk_d4_incident', 'We can rule out a code change.', '코드 변경은 원인에서 빼도 돼요.', '"Rule out" = decide that something is not the cause.', 'rule out은 그것이 원인이 아니라고 배제한다는 뜻입니다.', 'office'),
  ('dk_d4_incident.on_your_end', 'dk_d4_incident', 'Did anything change on your end?', '그쪽에서 바뀐 게 있어요?', '"On your end" = on your side, in your part of the system.', 'on your end는 당신 쪽, 당신이 맡은 부분이라는 뜻입니다.', 'office'),
  ('dk_d4_incident.stop_the_bleeding', 'dk_d4_incident', 'Let''s stop the bleeding first.', '우선 피해부터 막아요.', 'Limit the damage now, and fix the real cause afterward.', '지금은 피해를 줄이고 진짜 원인은 나중에 고치자는 뜻입니다.', 'office'),
  ('dk_d4_incident.workaround', 'dk_d4_incident', 'as a workaround', '임시방편으로', 'A workaround avoids a problem without really fixing it.', 'workaround는 문제를 제대로 고치지 않고 피해 가는 방법입니다.', 'office'),
  ('dk_d4_incident.mitigated', 'dk_d4_incident', 'It''s mitigated now, and we''re monitoring it.', '지금은 완화됐고, 지켜보는 중이에요.', '"Mitigated" = the impact has stopped, even if the cause is not fixed yet.', 'mitigated는 원인은 아직이어도 영향은 멈췄다는 뜻입니다.', 'office'),
  ('dk_d4_incident.postmortem', 'dk_d4_incident', 'I''ll write up a postmortem.', '사후 분석 보고서를 쓸게요.', 'A postmortem explains what happened, why, and how to prevent it. "Write up" = write a report.', 'postmortem은 무슨 일이 왜 일어났고 어떻게 막을지 설명하는 문서입니다. write up은 보고서를 쓴다는 뜻입니다.', 'office');

-- dk_d5_demo: Sharing the credit

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d5_demo', 1, 'priya',
   'Friday. The team and a few people from sales are in the meeting room. Jun is holding his laptop tightly.', '금요일입니다. 회의실에 팀원들과 영업팀 몇 명이 있습니다. 준이 노트북을 꼭 쥐고 있습니다.',
   'Okay, demo time! Derek, do you want to show us the card payment fix?', 'Say Jun did the heavy lifting on that one, so you will hand it over to him.', '그 일은 준이 거의 다 했으니 그에게 넘기겠다고 하세요.',
   '[{"all":["heavy lifting"]},{"all":["hand it over"]},{"all":["hand it off"]},{"any":["credit"]},{"all":["let jun"]}]',
   'Actually, Jun did the heavy lifting on that one, so I''ll hand it over to him.',
   '["Actually, I did all of it myself over the weekend.","Actually, I''d rather have the soup today.","Actually, the bus stop is across the street."]',
   '["Give the credit to the person who did the work.","Key words: heavy lifting, hand it over"]', '["일을 한 사람에게 공을 돌리세요.","핵심 단어: heavy lifting, hand it over"]',
   'priya', 'Love it. Jun, you''re up first!', '좋아요. 준, 첫 순서예요!'),
  ('dk_d5_demo', 2, 'priya',
   'Jun finishes his demo, and people clap. Someone from sales raises a hand.', '준이 데모를 마치자 사람들이 박수를 칩니다. 영업팀의 누군가가 손을 듭니다.',
   'A question from sales: how many failed payments will this save us per month? Derek?', 'Say you do not have that number off the top of your head, and you will get back to them by Monday.', '그 숫자는 지금 바로 기억나지 않으니 월요일까지 알려 주겠다고 하세요.',
   '[{"all":["top of my head"]},{"all":["get back to"]},{"all":["find out"]},{"all":["look into"]}]',
   'I don''t have that number off the top of my head. Let me get back to you by Monday.',
   '["I don''t have any cash on me. Do you take cards?","About two fifty. Just tap your card.","I don''t have a rewards card yet."]',
   '["Do not guess. Promise an answer and a date.","Key words: off the top of my head, get back to you"]', '["짐작하지 말고, 답과 날짜를 약속하세요.","핵심 단어: off the top of my head, get back to you"]',
   'priya', 'Fair enough. I''ll note it as an action item.', '그럴 수 있죠. 할 일 목록에 적어 둘게요.'),
  ('dk_d5_demo', 3, 'priya',
   'Priya looks at the agenda.', '프리야가 안건을 봅니다.',
   'Your turn. Anything to show for gift cards?', 'Say it is still a work in progress: the first ticket is done, and the second is on track for next week.', '아직 진행 중이라고 하세요. 첫 티켓은 끝났고, 두 번째는 다음 주 일정대로 가고 있다고요.',
   '[{"all":["work in progress"]},{"all":["in progress"]},{"all":["on track"]}]',
   'It''s still a work in progress. The first ticket is done, and the second is on track for next week.',
   '["It''s still raining, so I''ll wait inside.","It''s still warm. They just came out of the oven.","The first floor is the lobby, and HR is on three."]',
   '["Say what is done and what is coming.","Key words: work in progress, on track"]', '["끝난 것과 앞으로 할 것을 말하세요.","핵심 단어: work in progress, on track"]',
   'priya', 'Good enough for me. Let''s switch to the retro.', '그 정도면 충분해요. 회고로 넘어가요.'),
  ('dk_d5_demo', 4, 'priya',
   'Priya draws two columns on the whiteboard.', '프리야가 화이트보드에 두 칸을 그립니다.',
   'What went well this sprint?', 'Give a shout-out to Sam for the quick fix during the incident, and say Jun ramped up really fast.', '장애 때 빠르게 고쳐 준 샘을 칭찬하고, 준이 정말 빨리 적응했다고 하세요.',
   '[{"all":["shout out"]},{"any":["shoutout","kudos","incident"]},{"all":["ramped up"]}]',
   'Shout-out to Sam for the quick fix during the incident. And Jun ramped up really fast.',
   '["The burger went well with the fries.","My weekend went well. We had a barbecue.","The bus was on time every single day."]',
   '["Praise people by name for specific things.","Key words: shout-out to, ramped up"]', '["이름을 들어 구체적인 일을 칭찬하세요.","핵심 단어: shout-out to, ramped up"]',
   'priya', 'Agreed on both. Kudos, Sam and Jun!', '둘 다 동의해요. 샘, 준, 잘했어요!'),
  ('dk_d5_demo', 5, 'priya',
   'She points at the second column.', '그녀가 두 번째 칸을 가리킵니다.',
   'And what could we do better?', 'Say too much changed mid-sprint, and going forward the team should lock the scope once the sprint starts.', '스프린트 도중에 너무 많이 바뀌었으니, 앞으로는 스프린트가 시작되면 범위를 고정하자고 하세요.',
   '[{"all":["mid sprint"]},{"any":["scope","requirements"]},{"all":["going forward"]}]',
   'Too much changed mid-sprint. Going forward, let''s lock the scope once the sprint starts.',
   '["Too much salt. Next time, I''d order the salad.","We could get better seats if we come early.","Too much traffic. Let''s leave before five."]',
   '["Name the problem, then suggest a rule for the future.","Key words: mid-sprint, going forward, scope"]', '["문제를 말한 뒤 앞으로의 규칙을 제안하세요.","핵심 단어: mid-sprint, going forward, scope"]',
   'priya', 'Ouch, but fair. I''ll push back on late requests myself.', '아프지만 맞는 말이에요. 늦게 들어오는 요청은 제가 막을게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d5_demo.heavy_lifting', 'dk_d5_demo', 'Jun did the heavy lifting on that one.', '그건 준이 거의 다 했어요.', '"Do the heavy lifting" = do the hardest part of the work. A generous way to give credit.', 'do the heavy lifting은 가장 힘든 부분을 했다는 뜻입니다. 공을 돌리는 너그러운 표현입니다.', 'meeting'),
  ('dk_d5_demo.hand_it_over', 'dk_d5_demo', 'I''ll hand it over to him.', '그에게 넘길게요.', 'Passes the floor to another speaker.', '발언 순서를 다른 사람에게 넘길 때 씁니다.', 'meeting'),
  ('dk_d5_demo.top_of_my_head', 'dk_d5_demo', 'I don''t have that number off the top of my head.', '그 숫자는 지금 바로 기억나지 않아요.', '"Off the top of my head" = from memory, without checking.', 'off the top of my head는 확인하지 않고 기억만으로라는 뜻입니다.', 'meeting'),
  ('dk_d5_demo.get_back_to_you', 'dk_d5_demo', 'Let me get back to you by Monday.', '월요일까지 알려 드릴게요.', 'Better than guessing. Always add a date.', '짐작하는 것보다 낫습니다. 날짜를 꼭 덧붙이세요.', 'meeting'),
  ('dk_d5_demo.action_item', 'dk_d5_demo', 'an action item', '후속 조치 항목', 'A task someone must do after a meeting.', '회의 뒤에 누군가 해야 하는 일입니다.', 'meeting'),
  ('dk_d5_demo.work_in_progress', 'dk_d5_demo', 'It''s still a work in progress.', '아직 진행 중이에요.', 'Not finished yet, but moving.', '아직 끝나지 않았지만 진행되고 있다는 뜻입니다.', 'meeting'),
  ('dk_d5_demo.shout_out', 'dk_d5_demo', 'Shout-out to Sam for the quick fix.', '빠르게 고쳐 준 샘에게 박수를 보내요.', 'Public thanks or praise for someone. "Kudos" means the same.', '누군가를 공개적으로 칭찬하거나 고마워하는 말입니다. kudos도 같은 뜻입니다.', 'meeting'),
  ('dk_d5_demo.going_forward', 'dk_d5_demo', 'Going forward, let''s lock the scope.', '앞으로는 범위를 고정해요.', '"Going forward" = from now on.', 'going forward는 앞으로는, 이제부터는이라는 뜻입니다.', 'meeting');

-- dk_d5_happy_hour: Rounding up the team

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d5_happy_hour', 1, 'tom',
   'Friday afternoon. Jun has already told you he is too tired to come tonight. You stop at the front desk on your way out.', '금요일 오후입니다. 준은 너무 피곤해서 오늘은 못 가겠다고 이미 말했습니다. 나가는 길에 프런트 데스크에 들릅니다.',
   'Happy Friday, Derek! Heading out already?', 'Say a bunch of you are going to happy hour at the Anchor, and ask if he is in.', '몇 명이 앵커로 해피아워를 간다고 하고, 같이 갈 건지 물어보세요.',
   '[{"all":["happy hour"]},{"all":["you in"]},{"all":["join us"]},{"any":["anchor"]}]',
   'Almost. A bunch of us are going to happy hour at the Anchor. Are you in?',
   '["Almost. I just need to pick up my dry cleaning.","Not yet. I have a meeting with Maya at five.","Yes, I''m heading to the airport."]',
   '["Say where the group is going and ask \\"Are you in?\\"","Key words: happy hour, are you in"]', '["어디로 가는지 말하고 \\"Are you in?\\"으로 물어보세요.","핵심 단어: happy hour, are you in"]',
   'tom', 'The Anchor? With the patio? Count me in.', '앵커요? 야외 자리 있는 데? 저도 갈게요.'),
  ('dk_d5_happy_hour', 2, 'tom',
   'Tom checks the clock above the elevators.', '톰이 엘리베이터 위의 시계를 봅니다.',
   'What time are you all heading over?', 'Say around five thirty, and that the first round is on you.', '다섯 시 반쯤이고, 첫 잔은 당신이 산다고 하세요.',
   '[{"all":["five thirty"]},{"all":["5 30"]},{"all":["on me"]},{"all":["first round"]}]',
   'Around five thirty. And the first round''s on me.',
   '["Around the corner, next to the bank.","About twenty minutes by bus.","Every other Friday, by direct deposit."]',
   '["Give the time, then offer to pay for the first drinks.","Key words: five thirty, first round''s on me"]', '["시간을 말하고, 첫 잔을 사겠다고 하세요.","핵심 단어: five thirty, first round''s on me"]',
   'tom', 'Now you''re talking!', '그거 좋네요!'),
  ('dk_d5_happy_hour', 3, 'tom',
   'He grins.', '그가 활짝 웃습니다.',
   'So what''s the occasion?', 'Say the team survived an incident and Jun made it through his first week.', '팀이 장애를 무사히 넘겼고 준이 첫 주를 잘 마쳤다고 하세요.',
   '[{"all":["first week"]},{"any":["incident","survived","celebrate","celebrating"]}]',
   'We survived an incident, and Jun made it through his first week. That calls for a drink.',
   '["No occasion. I''m just here to pick up a package.","It''s my neighbor''s car, actually.","It''s casual. Jeans are fine."]',
   '["Give the reasons to celebrate.","Key words: survived, first week, calls for"]', '["축하할 이유를 말하세요.","핵심 단어: survived, first week, calls for"]',
   'tom', 'I''ll drink to that.', '그건 건배할 만하네요.'),
  ('dk_d5_happy_hour', 4, 'tom',
   'Tom looks toward the elevators.', '톰이 엘리베이터 쪽을 봅니다.',
   'Is Jun coming along?', 'Say he is taking a rain check: he is wiped out, but he will come next time.', '그는 다음으로 미뤘다고 하세요. 녹초가 됐지만 다음번에는 오겠다고 했다고요.',
   '[{"all":["rain check"]},{"all":["next time"]},{"all":["wiped out"]}]',
   'He''s taking a rain check. He''s pretty wiped out, but he says he''ll come next time.',
   '["He''s taking the bus to the airport.","He''s taking a photo for his badge.","He''s at the dentist until four."]',
   '["\\"Take a rain check\\" = say no now, yes another time.","Key words: rain check, next time"]', '["take a rain check는 이번엔 못 가지만 다음에 가겠다는 뜻입니다.","핵심 단어: rain check, next time"]',
   'tom', 'Poor guy. The first week will do that to you.', '안됐네요. 첫 주는 원래 그래요.'),
  ('dk_d5_happy_hour', 5, 'tom',
   'Tom starts to tidy up the front desk.', '톰이 프런트 데스크를 정리하기 시작합니다.',
   'Mind if I bring Linda? She said she was free tonight.', 'Say not at all, the more the merrier, and you will save them both a seat.', '물론 괜찮다고, 많을수록 좋다고 하고, 두 사람 자리를 맡아 두겠다고 하세요.',
   '[{"all":["more the merrier"]},{"all":["save you"]},{"all":["not at all"]},{"all":["bring her"]}]',
   'Not at all. The more, the merrier. I''ll save you both a seat.',
   '["Yes, this seat is taken.","She moved to the second floor.","Sorry, I don''t have a pen."]',
   '["Answer \\"Mind if …?\\" with \\"Not at all\\" to say yes.","Key words: not at all, the more the merrier"]', '["\\"Mind if …?\\"에는 \\"Not at all\\"이 좋다는 대답입니다.","핵심 단어: not at all, the more the merrier"]',
   'tom', 'See you there. Let me just lock up here.', '거기서 봐요. 여기 문단속만 하고요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_d5_happy_hour.a_bunch_of_us', 'dk_d5_happy_hour', 'A bunch of us are going to happy hour.', '몇 명이 같이 해피아워에 가요.', '"A bunch of us" = a group of us. Casual.', 'a bunch of us는 우리 여럿이라는 편한 표현입니다.', 'small-talk'),
  ('dk_d5_happy_hour.count_me_in', 'dk_d5_happy_hour', 'Count me in.', '저도 갈게요.', 'Answers "Are you in?" The opposite is "Count me out."', '"Are you in?"에 대한 대답입니다. 반대는 "Count me out."입니다.', 'small-talk'),
  ('dk_d5_happy_hour.first_round', 'dk_d5_happy_hour', 'The first round''s on me.', '첫 잔은 제가 살게요.', 'A round is one drink for everyone in the group.', 'round는 일행 모두에게 한 잔씩 돌리는 것입니다.', 'small-talk'),
  ('dk_d5_happy_hour.the_occasion', 'dk_d5_happy_hour', 'What''s the occasion?', '무슨 좋은 일 있어요?', 'Asks what is being celebrated.', '무엇을 축하하는지 묻는 말입니다.', 'small-talk'),
  ('dk_d5_happy_hour.calls_for', 'dk_d5_happy_hour', 'That calls for a drink.', '그건 한잔해야 할 일이죠.', '"That calls for …" = that is a good reason for ….', '"That calls for …"는 그럴 만한 이유가 된다는 뜻입니다.', 'small-talk'),
  ('dk_d5_happy_hour.taking_rain_check', 'dk_d5_happy_hour', 'He''s taking a rain check.', '그는 다음으로 미뤘어요.', 'He said no this time but wants to come another time.', '이번엔 못 오지만 다음에는 오고 싶다는 뜻입니다.', 'small-talk'),
  ('dk_d5_happy_hour.more_the_merrier', 'dk_d5_happy_hour', 'The more, the merrier.', '많을수록 좋죠.', 'More people make it more fun. Said when someone asks to bring a friend.', '사람이 많을수록 즐겁다는 뜻입니다. 누가 친구를 데려와도 되냐고 물을 때 씁니다.', 'small-talk'),
  ('dk_d5_happy_hour.save_a_seat', 'dk_d5_happy_hour', 'I''ll save you both a seat.', '두 분 자리 맡아 둘게요.', '"Save a seat" = keep a seat free for someone.', 'save a seat는 누군가를 위해 자리를 맡아 둔다는 뜻입니다.', 'small-talk');

-- dk_w_market: Groceries for the barbecue

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w_market', 1, 'mike',
   'A sunny weekend. Your cart is full of burger patties, buns, and corn. Mike starts scanning.', '화창한 주말입니다. 카트에 버거 패티와 빵, 옥수수가 가득합니다. 마이크가 바코드를 찍기 시작합니다.',
   'Hey, Derek! Whoa, that''s a lot of burgers. Having a party?', 'Say you are having some friends over for a barbecue this weekend.', '이번 주말에 친구들을 집에 불러 바비큐를 한다고 하세요.',
   '[{"any":["barbecue","bbq","cookout","grilling","grill"]},{"all":["friends over"]}]',
   'Yeah, I''m having some friends over for a barbecue this weekend.',
   '["Yeah, I''m flying out first thing tomorrow.","No, I''m here to fix the freezer.","Yeah, I work the evening shift."]',
   '["Explain the reason for all the food.","Key words: friends over, barbecue"]', '["음식을 많이 사는 이유를 설명하세요.","핵심 단어: friends over, barbecue"]',
   'mike', 'Nice! Perfect weather for it.', '좋네요! 바비큐 하기 딱 좋은 날씨예요.'),
  ('dk_w_market', 2, 'mike',
   'Mike holds up your bag of corn.', '마이크가 옥수수 봉지를 들어 보입니다.',
   'Heads-up: corn on the cob is five for two dollars this week, and you''ve only got three. Want to grab two more?', 'Say good catch, you will run and grab two more, and you will be right back.', '잘 봤다고 하고, 얼른 두 개를 더 가져오겠다고, 금방 오겠다고 하세요.',
   '[{"any":["grab"]},{"all":["be right back"]},{"all":["two more"]},{"all":["good catch"]}]',
   'Good catch. I''ll run and grab two more. I''ll be right back.',
   '["Good question. I''ll ask my manager.","Good night. I''ll see you tomorrow.","No, thanks. I''m allergic to shellfish."]',
   '["Thank him for noticing and say you will return quickly.","Key words: good catch, grab two more, be right back"]', '["알려 줘서 고맙다고 하고 곧 돌아오겠다고 하세요.","핵심 단어: good catch, grab two more, be right back"]',
   'mike', 'No problem. I''ll keep ringing you up.', '괜찮아요. 계속 계산하고 있을게요.'),
  ('dk_w_market', 3, 'mike',
   'You come back with two more ears of corn.', '옥수수 두 개를 더 들고 돌아옵니다.',
   'Did you find everything else okay?', 'Say almost: you could not find the charcoal, and ask which aisle it is in.', '거의 다 찾았는데 숯을 못 찾았다고 하고, 몇 번 통로에 있는지 물어보세요.',
   '[{"any":["charcoal","aisle"]},{"all":["could not find"]}]',
   'Almost. I couldn''t find the charcoal. Which aisle is it in?',
   '["Almost. I''m still waiting on the API keys.","Yes, I found a great apartment downtown.","Almost. The bus was a few minutes late."]',
   '["Say what you could not find and ask where it is.","Key words: couldn''t find, charcoal, which aisle"]', '["못 찾은 물건을 말하고 어디 있는지 물어보세요.","핵심 단어: couldn''t find, charcoal, which aisle"]',
   'mike', 'Sorry, we''re out. The truck comes Monday. Try Fairview Hardware on Lake Avenue.', '죄송해요, 다 떨어졌어요. 월요일에 들어와요. 레이크 애비뉴의 페어뷰 철물점에 가 보세요.'),
  ('dk_w_market', 4, 'mike',
   'Four full paper bags sit at the end of the belt.', '벨트 끝에 가득 찬 종이봉투 네 개가 놓여 있습니다.',
   'Your total''s sixty-four twenty. Do you need a hand out to your car with all that?', 'Say no, thanks, you can manage, and you are parked right out front.', '괜찮다고, 혼자 들 수 있다고 하고, 바로 앞에 주차했다고 하세요.',
   '[{"any":["manage"]},{"all":["got it"]},{"all":["i am good"]},{"any":["parked"]}]',
   'No, thanks. I can manage. I''m parked right out front.',
   '["Yes, I''d like a wake-up call at six.","No, thanks. I''m just looking.","Yes, a window seat, please."]',
   '["Turn down the help politely.","Key words: I can manage, parked out front"]', '["도움을 정중히 사양하세요.","핵심 단어: I can manage, parked out front"]',
   'mike', 'Alright. Enjoy the barbecue!', '알겠어요. 바비큐 맛있게 하세요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_w_market.having_a_party', 'dk_w_market', 'Having a party?', '파티 하세요?', 'Short for "Are you having a party?" Cashiers often chat about what you buy.', '"Are you having a party?"를 줄인 말입니다. 계산원은 산 물건을 두고 말을 걸곤 합니다.', 'small-talk'),
  ('dk_w_market.heads_up', 'dk_w_market', 'Heads-up: corn is on sale.', '참고로, 옥수수가 할인 중이에요.', '"Heads-up" introduces a useful warning or tip.', 'heads-up은 유용한 경고나 정보를 알릴 때 씁니다.', 'shopping'),
  ('dk_w_market.five_for_two', 'dk_w_market', 'five for two dollars', '다섯 개에 2달러', 'A common sale price. You often need to buy all five to get it.', '흔한 할인 표시입니다. 다섯 개를 다 사야 적용되는 경우가 많습니다.', 'shopping'),
  ('dk_w_market.good_catch', 'dk_w_market', 'Good catch.', '잘 봤어요.', 'Thanks someone for noticing a mistake or something you missed.', '실수나 놓친 것을 알아봐 준 사람에게 하는 말입니다.', 'small-talk'),
  ('dk_w_market.be_right_back', 'dk_w_market', 'I''ll be right back.', '금방 올게요.', 'You are leaving for a very short time.', '아주 잠깐 자리를 비울 때 씁니다.', 'small-talk'),
  ('dk_w_market.which_aisle', 'dk_w_market', 'Which aisle is it in?', '몇 번 통로에 있어요?', 'An aisle is a row between the shelves. The "s" is silent.', 'aisle은 진열대 사이의 통로입니다. s는 발음하지 않습니다.', 'shopping'),
  ('dk_w_market.were_out', 'dk_w_market', 'Sorry, we''re out.', '죄송해요, 다 떨어졌어요.', '"We''re out (of it)" = there is none left.', 'we''re out (of it)은 남은 것이 없다는 뜻입니다.', 'shopping'),
  ('dk_w_market.need_a_hand', 'dk_w_market', 'Do you need a hand out to your car?', '차까지 들어 드릴까요?', '"A hand" = help. Answer "I can manage, thanks" if you do not need it.', 'a hand는 도움을 뜻합니다. 필요 없으면 "I can manage, thanks."라고 답합니다.', 'shopping');

-- dk_w_park: Carl and the lawn mower

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w_park', 1, 'carl',
   'A sunny morning in Seaside Park. Carl is on his usual bench with the newspaper.', '시사이드 공원의 화창한 아침입니다. 칼이 늘 앉는 벤치에서 신문을 보고 있습니다.',
   'Well, if it isn''t Derek! Haven''t seen you at the bus stop lately. What have you been up to?', 'Say work has been crazy, and you are finally catching up on yard work this weekend.', '일이 정신없이 바빴고, 이번 주말에야 밀린 마당 일을 한다고 하세요.',
   '[{"all":["yard work"]},{"any":["lawn","yard","mowing"]},{"any":["crazy","busy","hectic"]}]',
   'Hey, Carl! Work''s been crazy. I''m finally catching up on yard work this weekend.',
   '["Hey, Carl! I''m looking for gate twelve.","Hey, Carl! I''d like to open a checking account.","Hey, Carl! Could you ring me up?"]',
   '["Say how work has been and what you are doing now.","Key words: crazy, catching up on yard work"]', '["일이 어땠는지, 지금 무엇을 하는지 말하세요.","핵심 단어: crazy, catching up on yard work"]',
   'carl', 'Good man. A lawn won''t mow itself.', '잘하고 있구먼. 잔디가 저절로 깎이진 않으니까.'),
  ('dk_w_park', 2, 'carl',
   'Carl folds his newspaper.', '칼이 신문을 접습니다.',
   'Speaking of which, how''s that old mower of yours? Still giving you trouble?', 'Say it will not start, you think it is the spark plug, and ask if he would mind taking a look.', '시동이 안 걸리는데 점화 플러그 같다고 하고, 한번 봐 줄 수 있는지 물어보세요.',
   '[{"all":["will not start"]},{"all":["take a look"]},{"all":["taking a look"]},{"all":["spark plug"]}]',
   'It won''t start. I think it''s the spark plug. Would you mind taking a look sometime?',
   '["It starts at ten, in the big meeting room.","It''s going well. Everyone has been helpful.","It comes with fries or a side salad."]',
   '["Describe the problem, then ask politely with \\"Would you mind …ing?\\"","Key words: won''t start, would you mind taking a look"]', '["문제를 설명한 뒤 \\"Would you mind …ing?\\"로 정중히 부탁하세요.","핵심 단어: won''t start, would you mind taking a look"]',
   'carl', 'For you? Sure. I fixed buses for thirty years. A mower is nothing.', '자네 부탁인데, 그럼. 버스를 30년 고쳤어. 잔디 깎는 기계쯤이야.'),
  ('dk_w_park', 3, 'carl',
   'He takes a small notebook out of his shirt pocket.', '그가 셔츠 주머니에서 작은 수첩을 꺼냅니다.',
   'I''ll come by this afternoon. River Road, right? The house with the blue door?', 'Say that is the one, and invite him to stay for the barbecue: you are firing up the grill around four.', '맞다고 하고, 바비큐도 먹고 가라고 초대하세요. 네 시쯤 그릴에 불을 붙인다고요.',
   '[{"any":["barbecue","bbq","cookout","grill","burgers"]},{"all":["stay for"]},{"all":["come over"]}]',
   'That''s the one. And stay for the barbecue! I''m firing up the grill around four.',
   '["That''s the one. It leaves from gate twelve.","No, I live in the apartments on Maple Street.","That''s the one. I''ll take it in a medium."]',
   '["Confirm, then invite him to stay and eat.","Key words: stay for the barbecue, fire up the grill"]', '["맞다고 확인하고, 남아서 먹고 가라고 초대하세요.","핵심 단어: stay for the barbecue, fire up the grill"]',
   'carl', 'Burgers? You don''t have to ask me twice.', '버거? 두 번 말할 필요 없지.'),
  ('dk_w_park', 4, 'carl',
   'Carl writes "4 p.m." in his notebook.', '칼이 수첩에 "오후 4시"라고 적습니다.',
   'What can I bring?', 'Tell him to just bring himself, because you have everything covered.', '몸만 오라고 하세요. 다 준비돼 있다고요.',
   '[{"all":["bring yourself"]},{"any":["covered","nothing"]},{"all":["all set"]}]',
   'Just bring yourself. I''ve got everything covered.',
   '["Just bring your boarding pass and a photo ID.","Bring the laptop to the help desk by four.","Bring it back within thirty days with the receipt."]',
   '["A host often says guests do not need to bring anything.","Key words: just bring yourself, covered"]', '["주인은 손님에게 아무것도 가져올 필요 없다고 말하곤 합니다.","핵심 단어: just bring yourself, covered"]',
   'carl', 'I''ll bring my potato salad anyway. It''s famous on three bus routes.', '그래도 내 감자 샐러드는 가져가지. 버스 노선 세 개에서 유명하거든.'),
  ('dk_w_park', 5, 'carl',
   'Your phone buzzes in your pocket. It is only a message from a friend.', '주머니에서 전화기가 울립니다. 친구가 보낸 메시지일 뿐입니다.',
   'You young people work too hard. They don''t call you on the weekend, do they?', 'Say you are on call this week, but it has been quiet so far, knock on wood.', '이번 주는 온콜 담당이지만 아직까지는 조용하다고, 계속 그러길 빈다고 하세요.',
   '[{"all":["on call"]},{"all":["knock on wood"]},{"any":["quiet"]}]',
   'I''m on call this week, but it''s been quiet so far. Knock on wood.',
   '["I''m on the third floor, by the window.","I''m on a diet, so no pie for me.","I''m on my way to the airport."]',
   '["\\"Knock on wood\\" is said so that good luck continues.","Key words: on call, quiet, knock on wood"]', '["knock on wood는 행운이 이어지길 바랄 때 하는 말입니다.","핵심 단어: on call, quiet, knock on wood"]',
   'carl', 'Knock on wood is right. See you at four, Derek!', '그래, 부정 타면 안 되지. 네 시에 보세, 데릭!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('dk_w_park.if_it_isnt', 'dk_w_park', 'Well, if it isn''t Derek!', '아니, 이게 누구야, 데릭 아닌가!', 'A happy, surprised greeting for someone you know.', '아는 사람을 반갑고 놀랍게 맞이하는 인사입니다.', 'small-talk'),
  ('dk_w_park.been_up_to', 'dk_w_park', 'What have you been up to?', '그동안 어떻게 지냈어요?', 'Asks what someone has been doing lately.', '요즘 무엇을 하며 지냈는지 묻는 말입니다.', 'small-talk'),
  ('dk_w_park.catching_up_on', 'dk_w_park', 'I''m catching up on yard work.', '밀린 마당 일을 하고 있어요.', '"Catch up on" = do things you did not have time for earlier.', 'catch up on은 전에 시간이 없어 못 한 일을 한다는 뜻입니다.', 'small-talk'),
  ('dk_w_park.giving_trouble', 'dk_w_park', 'Is it still giving you trouble?', '아직도 말썽이에요?', 'Said about a machine that does not work well.', '잘 작동하지 않는 기계에 대해 쓰는 말입니다.', 'small-talk'),
  ('dk_w_park.would_you_mind', 'dk_w_park', 'Would you mind taking a look sometime?', '언제 한번 봐 주실 수 있을까요?', '"Would you mind …ing?" is a very polite way to ask a favor.', '"Would you mind …ing?"는 아주 정중하게 부탁하는 표현입니다.', 'small-talk'),
  ('dk_w_park.fire_up_the_grill', 'dk_w_park', 'I''m firing up the grill around four.', '네 시쯤 그릴에 불을 붙일 거예요.', '"Fire up" = start (a grill, an engine, a laptop).', 'fire up은 그릴이나 엔진, 노트북을 켠다는 뜻입니다.', 'food'),
  ('dk_w_park.bring_yourself', 'dk_w_park', 'Just bring yourself.', '몸만 오세요.', 'A host''s answer to "What can I bring?" Guests often bring something anyway.', '"What can I bring?"에 대한 주인의 대답입니다. 그래도 손님은 흔히 무언가를 가져옵니다.', 'small-talk'),
  ('dk_w_park.knock_on_wood', 'dk_w_park', 'Knock on wood.', '이대로만 가길. (부정 타지 않길.)', 'Said after mentioning good luck, so that it does not end.', '좋은 일을 말한 뒤, 그 운이 끝나지 않길 바라며 하는 말입니다.', 'small-talk');

-- Derek's calendar, days 1-7.

REPLACE INTO calendar (day, time, title, title_ko, place, episode, hero) VALUES
